window.PMM_NAHJ_TRANSCRIPT_ACCEPT({"group":"wisdoms","number":289,"source":"حکمت 289.docx","mode":"explicit-parts","parts":["حکمت 289\nبخش اول \nمتن:\nوَ قَالَ (علیه السلام): كَانَ لِي فِيمَا مَضَى أَخٌ فِي اللَّهِ، وَ كَانَ [يُعَظِّمُهُ] يُعْظِمُهُ فِي عَيْنِي صِغَرُ الدُّنْيَا فِي عَيْنِهِ، وَ كَانَ خَارِجاً مِنْ سُلْطَانِ بَطْنِهِ، فَلَا يَشْتَهِي مَا لَا يَجِدُ وَ لَا يُكْثِرُ إِذَا وَجَدَ،\nترجمه:\nامام عليه السلام فرمود: در گذشته برادرى الهى و دينى داشتم (كه وصفش چنين بود): آنچه او را در نظرم بزرگ جلوه مى داد كوچكى دنيا در نظر او بود. او از تحت حكومت شكم خارج بود، ازاينرو آنچه نمى يافت اشتهايش را نداشت (و به دنبال آن نمى رفت) و آنچه را مى يافت زياد مصرف نمى كرد.\nتفسیر:\n💠وَ قَالَ (علیه السلام): کَانَ لِی فِیمَا مَضَى أَخٌ فِی اللَّهِ\nمن در گذشته برادرى الهى و دینى داشتم که وصفش چنین بود.\n🟢در این حکمت امیرالمومنین صفات و ویژگی های “برادر خدایی” خودشان را ذکر میکنند. نام این حکمت را\n“الگوی کامل انسانیت” میتوان گذاشت.\n⏪مقدمات حکمت :\n◀️ الف. این شخص که برادر خدایی امیرالمومنین است چه کسی است؟\nشارحان نهج البلاغه از گذشته تا حال مصادیقی برای این کلام معرفی کرده اند.\n+ برخی گفته اند این برادر خدایی امیرالمومنین شخص شخیص پیامبر است. البته برخی گفته اند جمله\n“کان ضعیفا مستضعفا” با وجود مبارک حضرت سازگار نیست.\n📗علامه شوشتری میگوید بعید است مقصود حضرت، پیامبر باشد. زیرا در دیگر احادیث حضرت جایی پیامبر را تنها به نام “اخ” ذکر نکرده بلکه “اخی و حبیبی و ابن عمی” آمده است که نشان دهنده احترام امیرالمومنین به پیامبر است.\n+ برخی گفته اند این شخص ابوذر غفاری است (ابن ابی الحدید میگوید در حالات ابوذر شجاعت ذکر نشده و شاید این شخص ابوذر نباشد).\n📗 علامه شوشتری به ابن ابی الحدید پاسخ میدهد که این چه توهینی است به جناب ابوذر؟\nابوذر در دوران بعد از رسول الله هرگز با خلفا سازش نکرد و در کمال شجاعت با آنها درگیر شد تا آنجا که او را به شام تبعید کردند، به ربذه تبعید کردند تا شهید شد.\n+ برخی گفته اند این شخص مقداد است که تاریخ نشان میدهد واجد این صفات و شرایط بوده.\n+ برخی گفته اند مقصود عثمان بن مظعون است که شخصیت والایی است.\n📗ابوالفرج اصفهانی در مقاتل الطالبیین میگوید: امیرالمومنین نام یکی از فرزندانشان را عثمان گذاشتند.\nوقتی از حضرت در مورد علت این نامگذاری و شباهت به نام خلیفه سوم پرسیدند حضرت فرمود:\nإِنَّمَا سَمَّیْتُهُ بِاسْمِ أَخِی عُثْمَانَ بْنِ مَظْعُون‏\nفرزندم را عثمان گذاشتم از شدت علاقه به ررادرم عثمان بن مظعون\n+ برخی نیز گفتند حضرت در اینجا از یک آرایه ادبی استفاده کرده است که شخص مثالی را برای ما توصیف کرده اند. شخصیتی که دارای صفات عالی اخلاقی باشد.\n+ و شاید حضرت خودشان را توصیف میکنند ولی برای اینکه تعریف از خود نباشد، آن را به اسم برادر الهی یاد میکنند.\n📗 مرحوم کمره ای میفرماید از اینجا میشود گفت اولین رمان نویس عالم امیرالمومنین بوده است. همانگونه که در تعریف زمان گفته اند.\n“قصه و ماجرای بلندی که جنبه تخیلی داشته باشد و شخص اتفاقی که برای خودش افتاده است را از زبان دیگری نقل میکند”\n🟢 در جمع بندی نظرات باید گفت دو قول بیشتر از بقیه بیان شده است:\nجناب ابوذر\nشخصی خیالی ،\nیا خود امیرالمومنین\n◀️ ب. دوستی باید خدایی باشد.\nبه خلاف دوستی های دنیایی و مادی که محور آن سود بردن و به مقصود رسیدن است، لذت بردن و کامجویی است، حضرت میفرماید معیار دوستی باید خدا باشند. اخوت و برادری باید حول محور محبت و اطاعت از خدا باشد.\nآن دوستی و رفاقتی ارزش مند است که\n” أَخٌ فِی اللَّهِ ” باشد.\n🔴 در باب برادر دینی درغررالحکم فرمودند:\nخیرُ الإخْوانِ مَن کانتْ فی اللّهِ مَودّتُهُ. بهترینِ برادران و رفیقان کسی است که دوستی و رفاقتش در راه خداوند باشد.\nالنَّاسُ إِخْوَانٌ فَمَنْ کَانَتْ أُخُوَّتُهُ فِی غَیْرِ ذَاتِ اللَّهِ فَإِنَّهَا تَحُوزُ عَدَاوَهً\nمردم با هم برادرند، پس هر کسی که برادری و رفاقتش برای خداوند نباشد در حقیقت{آن رفاقت} به دشمنی می انجامد،\nوَ ذَلِکَ قَوْلُهُ تَعَالَى الْأَخِلَّاءُ یَوْمَئِذٍ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلَّا الْمُتَّقِین‏\nهمچنان که خداوند متعال می فرماید: رفیقان در آن روز قیامت دشمنان یکدیگرند به جز پرهیزگاران.\n💠وَ قَالَ (علیه السلام): کَانَ لِی فِیمَا مَضَى أَخٌ فِی اللَّهِ\nمن در گذشته برادرى الهى و دینى داشتم که وصفش چنین بود.\n💠 وَ کَانَ یُعْظِمُهُ فِی عَیْنِی صِغَرُ الدُّنْیَا فِی عَیْنِهِ\nآنچه او را در نظرم بزرگ جلوه مى داد کوچکى دنیا در نظر او بود.\n♻️اولین وصف برادران خدایی امیرالمومنین کوچک دیدن دنیاست.\nمومن دنیا را ریز می بیند.\nافراد دنیا طلب و دنیا خواه به کوچکترین متاع دنیا دل بسته اند و برای رسیدن به آن تلاش میکنند، برای از دست دادن کوچکترین مواهب دنیایی به هم میریزند و زندگی شان تحت تاثیر قرار میگیرد.\nولی مومنین راستین کسانی هستند که دنیا با همه بزرگی و زرق و برقش برای آنها کوچک و ناچیز است.\nبه تعبیر قرآن کریم:\n《قُلْ مَتاعُ الدُّنْیا قَلیلٌ؛ نساء – ۷۴》\nبگو دنیا با تمام متاعش قلیل است.\nدر خطبه متقین فرمود:\nعَظُمَ الْخَالِقُ فِی أَنْفُسِهِمْ فَصَغُرَ مَا دُونَهُ فِی أَعْیُنِهِمْ\nخداوند، با عظمت در نظر آنها جلوه کرده ازاین رو ماسِوَى الله در نظر آنها کوچک است.\n🔴از امام سجاد پرسیدند:\nمَن أعظَمُ الناسِ فِی الدُّنیا خَطَراً ؟\nوالامقامترین انسانها کیست؟\nمَن لم یَجعَلْ للدنیا عِندَهُ خَطراً\nکسى که دنیا را براى خود بزرگ\nنشمارد، بزرگی انسان به بزرگ ندیدن دنیاست.\n❌بزرگ دیدن دنیا نتیجه خوبی ندارد.\nخداوند به حضرت موسی فرمود:\nیَا مُوسَى إِنَّ الدُّنْیَا دَارُ عُقُوبَهٍ عَاقَبْتُ فِیهَا آدَمَ عِنْدَ خَطِیئَتِهِ\nدنیا سراى کیفر است ؛ در آن، آدم را، به سبب خطایى که از او سر زد کیفر دادم\nوَ جَعَلْتُهَا مَلْعُونَهً ، مَلْعُونٌ مَا فِیهَا إِلَّا مَا کَانَ فِیهَا لِی\nو دنیا را ملعون قرار دادم و هرچه در دنیاست ملعون است، مگر آنچه براى من باشد .\nیَا مُوسَى إِنَّ عِبَادِیَ الصَّالِحِینَ زَهِدُوا فِی الدُّنْیَا بِقَدْرِ عِلْمِهِمْ\nای موسی دانایان به قدر علمشان از دنیا دوری میکنند.\nوَ سَائِرَ الْخَلْقِ رَغِبُوا فِیهَا بِقَدْرِ جَهْلِهِمْ\nو جاهلان به اندازه جهلشان به دنیا رغبت دارند.\nوَ مَا مِنْ أَحَدٍ عَظَّمَهَا فَقَرَّتْ عَیْنَاهُ فِیهَا\nو هیچ کسی نیست که دنیا را بزرگ شمارد، و چشمش روشن گردد.\nوَ لَمْ یُحَقِّرْهَا أَحَدٌ إِلَّا انْتَفَعَ بِهَا.\nو هیچ کسی نیست که آن را خُرد نشمرد ، مگر این که بِدان بهره مند مى شود.\n🟢 تا خدا را بزرگ نبینیم، دنیا را کوچک نخواهیم دید. در حکمت ۱۲۹ فرمود :\nعِظَمُ الْخَالِقِ عِنْدَکَ یُصَغِّرُ الْمَخْلُوقَ فِی عَیْنِکَ\nبزرگى خالق نزد تو، مخلوق را در چشمت کوچک مى کند\n🔴 مومنی که شروع هر نمازش با “الله اکبر” است نباید چیز دیگری جز خدا را بزرگ ببیند. اگر انسان واقعا به بزرگی خدا باور داشته باشد همه چیز در نگاه او کوچک میشود.\nاگر انسان به بزرگی و عظمت و قدرت خدا فکر کند، دنیا را کوچک میبیند.\nدر خطبه ۱۸۵ فرمود:\nلَوْ فَکَّرُوا فِی عَظِیمِ الْقُدْرَهِ وَ جَسِیمِ النِّعْمَهِ لَرَجَعُوا إِلَى الطَّرِیقِ\nاگر در عظمت و بزرگى نعمت بارى تعالى مى اندیشیدند، به راه راست بازمى گشتند\nوَ خَافُوا عَذَابَ الْحَرِیقِ\nو از عذاب آتش مى ترسیدند.\nوَ لَکِنِ الْقُلُوبُ عَلِیلَهٌ وَ الْبَصَائِرُ مَدْخُولَهٌ\nولى دلها بیمار است و دیده ها عیبناک. آیا به خردترین چیزى که آفریده است، نمى نگرند.\n🟢کوچک دیدن دنیا یعنی:\nکوچک دیدن غم های دنیا ،\nیعنی کوچک دیدن شادیهای دنیا،\nکوچک دیدن پست و مقام دنیا،\nکوچک دیدن عمر دنیا،\nکوچک دیدن سختیهای دنیا و….\n🔴پیامبر دنیا را کوچک دید، شما هم اینگونه باشید. درخطبه ۱۶۰ فرمود:\nفَتَأَسَّ بِنَبِیِّکَ الْأَطْیَبِ الْأَطْهَرِ،\nتو اى مسلمان، به پیامبر پاک و پاکیزه ات تأسّى بجوى،\nفَإِنَّ فِیهِ أُسْوَهً لِمَنْ تَأَسَّى…\nزیرا در او سرمشقى است براى آن کسی که مى خواهد تأسّى جوید.\nوَ أَحَبُّ الْعِبَادِ إِلَى اللَّهِ الْمُتَأَسِّی بِنَبِیِّهِ وَ الْمُقْتَصُّ لِأَثَرِهِ\nمحبوب ترین بندگان نزد خدا کسى است که به پیامبرش تأسّى جوید و در پى او گام بردارد.\nعُرِضَتْ عَلَیْهِ الدُّنْیَا، فَأَبَى أَنْ یَقْبَلَهَا\nدنیا به وى عرضه شد، ولى آن را نپذیرفت.\nوَ عَلِمَ أَنَّ اللَّهَ سُبْحَانَهُ أَبْغَضَ شَیْئاً فَأَبْغَضَهُ،\nاو مى دانست چه چیزى مبغوض خداست؟ آن را مبغوض مى شمرد،\nوَ حَقَّرَ شَیْئاً فَحَقَّرَهُ،\nوچه چیز نزد خدا حقیر است آن را حقیر مى دانست .\nوَ صَغَّرَ شَیْئاً فَصَغَّرَهُ\nو چه چیز نزد او کوچک است آن را کوچک مى دید.\nوَ لَوْ لَمْ یَکُنْ فِینَا إِلَّا حُبُّنَا مَا أَبْغَضَ اللَّهُ وَ رَسُولُهُ،\nو اگر در ما فقط یک نکته منفی باشد برای شقاوت ما کافی است:\nوَ تَعْظِیمُنَا مَا صَغَّرَ اللَّهُ وَ رَسُولُهُ، لَکَفَى بِهِ شِقَاقاً لِلَّهِ وَ مُحَادَّهً عَنْ أَمْرِ اللَّهِ.\nاینکه دوست داشته باشیم دنیایی که پیامبر با آن دشمنی میکرد و بزرگ بدانیم دنیایی که پیامبر آن را کوچک میشمرد.\nامیرالمومنین دنیا را کوچک دید، ما هم کوچک بشماریم.\n📗ابن عساکر در کتاب تاریخ دمشق از امیرالمومنین نقل میکند:\nأنَا الَّذی أهَنتُ الدُّنیا .\nمن کسی هستم که دنیا را بى مقدار شمردم.\nو زندگی حضرت هم همین مطلب را میرساند.\n💠وَ کَانَ خَارِجاً مِنْ سُلْطَانِ بَطْنِهِ\nاو از تحت حکومت شکم خارج بود،\n💠فَلَا یَشْتَهِی مَا لَا یَجِدُ\nآنچه نمى یافت اشتهایش را نداشت و به دنبال آن نمى رفت.\n💠 وَ لَا یُکْثِرُ إِذَا وَجَدَ\nو آنچه را مى یافت زیاد مصرف نمى کرد.\n⏪دومین وصف برادران خدایی امیرالمومنین تخت سلطه شکم نبودن است.\nخود این بخش در واقع سه وصف است:\n1⃣خارج بودن از سلطنت شکم:\nوَ کَانَ خَارِجاً مِنْ سُلْطَانِ بَطْنِهِ\nمعلوم است که خدای عده ای شکم آنها است و آن کسی که برای آنهای راه را تعیین میکند و به آنها امر و نهی میکند شکم است.\nو اتفاقا دشمن هم از همین سلطنت شکم استفاده میکند و افراد را مدیریت میکند.\nیک وقت به عده ای گرسنگی میدهد و آنها کم می آوردند و رها میکنند.\nیک وقت به عده ای زیاده میدهد و آنها را سیر میکند و آنها طغیان میکنند.\nولی اگر کسی اسیر و بنده بطن نبود، نه تهدید نه تطمیع، نه گرسنگی نه سیری نمی تواند او را به انحراف بکشاند.\n❌سلطنت شکم، باعث رسوایی انسان است. امام باقر علیه السلام فرمود:\nأکَلَ علیٌّ علیه السلام مِن تَمرٍ دَقَلٍ ثُمّ شَرِبَ علَیهِ الماءَ\nعلى علیه السلام مقدارى خرماى دَقَل (ارزان ترین نوع خرما) تناول کرد و سپس روى آن آب نوشید،\nثُمّ ضَرَبَ على بَطنِهِ ، و قالَ : مَن أدخَلَهُ بَطنُهُ النارَ فَأبعَدَهُ اللّه ُ ، ثُمّ تَمَثَّلَ\nو بعد دستى بر شکم خود زد و فرمود: هر که آتش وارد آن کند، خدا او را دور گرداند.آن گاه به این بیت تمثّل جُست:\nفَإنَّکَ مَهما تُعطِ بَطنَکَ سُؤلَهُ /\nو فَرْجَکَ نالا مُنتَهى الذَّمِّ أجمَعا\nتو هر گاه خواهش شکم و شهوتت را برآورى، منتهاى نکوهش و رسوایى را به بار می آورند.\n🔴شکم پرستی باعث سقوط انسان به حیوانیت است. در خطبه ۱۵۳ فرمود :\nإِنَّ الْبَهَائِمَ هَمُّهَا بُطُونُهَا\nبراستى که چرندگان فقط همّتشان مصروف شکمشان است.\n🟢هدف خلقت انسان شکم پرستی نیست. در نامه ۴۵ نیز فرمود:\nفَمَا خُلِقْتُ لِیَشْغَلَنِی أَکْلُ الطَّیِّبَاتِ\nمن آفریده نشده ام که غذاهاى پاکیزه و رنگارنگ مرا به خود مشغول دارد\nکَالْبَهِیمَهِ الْمَرْبُوطَهِ هَمُّهَا عَلَفُهَا،\nهمچون حیوان پروارى که تمام همّش علف اوست.\nأَوِ الْمُرْسَلَهِ شُغُلُهَا تَقَمُّمُهَا،\nو یا چون حیوان رها شده در بیابان و مرتع،\nتَکْتَرِشُ مِنْ أَعْلَافِهَا\nکه کارش جستجو کردن علف و پر کردن شکم از آن است.\nوَ تَلْهُو عَمَّا یُرَادُ بِهَا\nو از سرنوشتى که در انتظار اوست بى خبر است.\n🔴سلطنت شکم بر انسان، تبعیت از خلفا است. حضرت در خطبه شقشقیه در مورد خلیفه سوم فرمود:\nإِلَى أَنْ قَامَ ثَالِثُ الْقَوْمِ نَافِجاً حِضْنَیْهِ بَیْنَ نَثِیلِهِ وَ مُعْتَلَفِهِ\nو این وضع ادامه یافت تا سوّمى بپاخاست در حالى که از خوردن زیاد، دو پهلویش بر آمده بود\nوَ قَامَ مَعَهُ بَنُو أَبِیهِ یَخْضَمُونَ مَالَ اللَّهِ [خَضْمَ]\nو همّى جز جمع آورى و خوردن بیت المال نداشت و بستگان پدرش _بنى امیه_ به همکارى او برخاستند،\nخِضْمَهَ الْإِبِلِ نِبْتَهَ الرَّبِیعِ\nو همچون شتر گرسنه اى که در بهار به علفزار بیفتد و با ولع عجیبى گیاهان را ببلعد به خوردن اموال خدا مشغول شدند.\n2⃣ اشتها نداشتن به آنچه در دسترس نیست.\nفَلَا یَشْتَهِی مَا لَا یَجِدُ\nگاهی در زندگی پیش می آید که غذا دیر آماده میشود، یا غذا باب میل نیست، یا غذا سوخته و ته گرفته و … در این موارد انسان اصلا نباید زیاده خواهی کند و اشتهاء آن چیزی را داشته باشد که در دسترس نیست.\nمتاسفانه یکی از نقاط ضعف آقایان همین بخش است و این باعث دور شدن انسان از “برادری امیرالمومنین” خواهد شد.\n🟢 انسان باید مدیریت میل خود را نیز به دست بگیرد.\nدر جامعه فراوان دیده میشود که عده ای فقیر هستند و توان تهیه هر خوراک و پوشاک یا زندگی را ندارند، حضرت به آنها تووصیه میکند با مدیریت امیال و اشتهاء، جلوی نفوذ شیطان را بگیرند.\n📕در کتاب ثواب الاعمال دارد،\nامام صادق به یکی از اصحاب فرمود:\nأَنَّهُ قَالَ لِبَعْضِ أَصْحَابِهِ أَ مَا تَدْخُلُ اَلسُّوقَ أَمَا تَرَى اَلْفَاکِهَهَ تُبَاعُ وَ اَلشَّیْءَ مِمَّا تَشْتَهِیهِ\nآیا وارد بازار شده‌اى،و میوه یا چیزهاى دیگرى را که میل به آن دارى، دیده‌اى که در آنجا به فروش مى‌رسانند؟\nفَقُلْتُ بَلَى\nعرض کردم :بخدا سوگند که چنین است.\nفَقَالَ أَمَا إِنَّ لَکَ بِکُلِّ مَا تَرَاهُ وَ لاَ تَقْدِرُ عَلَى شِرَائِهِ وَ تَصْبِرُ عَلَیْهِ حَسَنَهً فرمود:آگاه باش که به ازاى هر چیزى که مى‌بینى و قدرت خرید آن را ندارى،به شرط‍‌ اینکه تهیدستى خود را تحمّل کنى،ثواب یک حسنه از آن تو خواهد بود.\n📗در مورد برخی بزرگان گفته شده که آنها اهل سیگار و دود بوده اند، یک وقتی سیگارشان تمام شده بود و دنبال سیگار از این مغازه به آن مغازه میرفتند، یک وقت به خودشان آمدند و گفتند\n“ما داریم سیگار میکشیم یا سیگار ما را به دنیال خود میکشد؟”\nو همانجا سیگار را ترک کردند.\nبرخی از ما نیز اشتها داریم به آنچه در دسترس نیست.\nبه مبل و لباس و خانه ای که توان خریدش را نداریم. به غذایی که الان نیست و خودمان و خانواده را بزحمت می اندازیم برای تهیه آن و….\n3⃣ زیاده روی نکردن در آن چیزهایی که در دسترس است.\nوَ کَانَ خَارِجاً مِنْ سُلْطَانِ بَطْنِهِ، فَلَا یَشْتَهِی مَا لَا یَجِدُ وَ لَا یُکْثِرُ إِذَا وَجَدَ\nهرگز بنده شکم نبود. چیزى را که نمى یافت، آرزو نمى کرد و چون مى یافت، بسیار به کار نمى برد.\n🟢دوستان امیرالمومنین کسانی هستند که اهل اعتدال اند، نه برده و بنده شکم اند، نه اگر چیزی نیست هوس میکنند، و اگر در دسترس بود زیاده روی نمی کنند.\n🔴پرهیز از پر خوری راز سلامتی و ایمان: قرآن کریم میفرماید:\n《 کُلُوا مِنْ طَیِّبَاتِ مَا رَزَقْنَاکُمْ وَ لَا تَطْغَوْ فِیهِ ؛ طه – ۸۱》\nاز خوراکیهاى پاکیزه‌اى که روزى شما کردیم، بخورید ولى‌ در آن زیاده‌روى نکنید.\n🟢 طغیان به معنای ناشکری نیز آمده است. درخطبه ۱۸۳ فرمود :\nأَسْهِرُوا عُیُونَکُمْ وَ أَضْمِرُوا بُطُونَکُمْ\nچشمها را در دل شب بیدار دارید، شکمها را لاغر کنید.\n💮پیامبر خدا صلی الله علیه واله فرمود:\nأَکْثَرُ مَا تَلِجُ بِهِ أُمَّتِی النَّارَ الْبَطْنُ وَالْفَرْجُ\nبیشترین چیزى که امت من به وسیله آن وارد آتش دوزخ مى شوند دو چیز است: شکم و شهوت.\nو باز هم فرمود :\nثَلاثٌ أَخَافُهُنَّ عَلَى أُمَّتِی مِنْ بَعْدِ\nسه چیز است که بعد از خودم بر امتم از آن بیمناکم.\nالضَّلالَهُ بَعْدَ الْمَعْرِفَهِ وَمَضَلاَّتُ الْفِتَنِ وَشَهْوَهُ الْبَطْنِ وَالْفَرْجِ\nگمراهى بعد از معرفت وآزمایش هاى گمراه کننده و شهوت شکم وشهوت جنسى.\n💮 امام باقر علیه السلام فرمود :\nمَا مِنْ عِبَادَهٍ أَفْضَلَ مِنْ عِفَّهِ بَطْنٍ وَفَرْجٍ هیچ عبادتى برتر از خویشتن دارى درمورد شکم و شهوت جنسى نیست.\n💮 پیامبر صلی الله علیه وآله:\nبِئْسَ العَوْنُ عَلَى الدِّینِ قَلْبٌ نَحیبٌ ، وَ بَطْنٌ رَغِیبٌ\nچه بد یاورى است براى دین:\nدل ترسو و شکم حریص!\n💮 پیامبر صلی الله علیه وآله :\nأفضَلُکُم مَنزِلَهً عندَ اللّه ِ تعالى أطوَلُکُم جُوعا و تَفَکُّرا ،\nبلند پایه ترین شما نزد خداوند متعال کسى است که مدتهاى طولانى ترى گرسنگى بکشد و به تفکر بپردازد ،\nو أبغَضُکُم إلَى اللّه ِ تعالى کُلُّ نَؤومٍ و أکُولٍ و شَروبٍ\nو منفورترین شما نزد خداوند متعال آن کسى است که پر خواب و پرخور و پر نوش باشد.\n💮 پیامبر صلی الله علیه وآله :\nالمُؤْمِنُ یَأْکُلُ فِی مِعَاءٍ واحِدٍ ، وَ الکَافِرُ یَأْکُلُ فِی سَبْعَهِ أمْعَاءٍ\nمؤمن یک شکم غذا مى خورد و کافر هفت شکم..\nإِنَّ اللَّهَ عَزَّ وَ جَلَّ یُبْغِضُ کَثْرَهَ الْأَکْلِ خداوند از پر خوری متنفر است.\nوَ قَالَ أَبُو عَبْدِ اللَّهِ: لَیْسَ لِابْنِ آدَمَ بُدٌّ مِنْ أَکْلَهٍ یُقِیمُ بِهَا صُلْبَهُ\nانسان ناچار باید غذا بخورد تا سرپا باشد،\nفَإِذَا أَکَلَ أَحَدُکُمْ طَعَاماً فَلْیَجْعَلْ ثُلُثَ بَطْنِهِ لِلطَّعَامِ\nپس هنگامى که شخصى غذا مى خورد یک سوم شکم را براى غذا در نظر بگیرد.\nوَ ثُلُثَ‏ بَطْنِهِ لِلشَّرَابِ\nویک سوم آنرا براى آشامیدنیها نگهدارد.\nوَ ثُلُثَ بَطْنِهِ لِلنَّفَسِ\nو یک سوم آنرا هم براى نفس کشیدن خالى بگذارد.\n📗ابن ابی الحدید میگوید:\nقِیلَ لِیُوسُفَ علیه السلام مَا لَکَ لاَ تَشْبَعُ وَ فِی یَدَیْکَ خَزَائِنُ مِصْرَ؟!\nبه حضرت یوسف گفتند تو که توانایی و برخورداری ، چرا یک وعده سیر نمیخوری؟\nقَالَ إِنِّی إِذَا شَبِعْتُ نَسِیتُ الْجَائِعِین\nگفت تا درد گرسنگان را فراموش نکنم.\n❌نه افراط در پرخوری نه تفریط در گرسنگی.\nدر حکمت ۱۰۸ در مورد انسان فرمود:انسان کسی است که\nإِنْ جَهَدَهُ الْجُوعُ قَعَدَ بِهِ الضَّعْفُ\nاگر گرسنگى پیدا کند ضعف زمین گیرش مى کند،\nوَ إِنْ أَفْرَطَ بِهِ الشِّبَعُ کَظَّتْهُ الْبِطْنَهُ\nو اگر پرخورى کند شکم پرورى او را به رنج انداخته راه نفس را بر او مى بندد.\nفَکُلُّ تَقْصِیرٍ بِهِ مُضِرٌّ وَ کُلُّ إِفْرَاطٍ لَهُ مُفْسِد.\nبه طور کلى هرگونه کمبود و تفریط به او زیان مى رساند و هرگونه افراط او را فاسد مى سازد.\n🟢حق شکم و بطن در رساله حقوق امام سجاد.\nوَ أَمَّا حَقُّ بَطْنِکَ فَأَنْ لاَ تَجْعَلَهُ وِعَاءً لِقَلِیل مِنَ الْحَرَامِ وَ لاَ لِکَثِیر\nاما حقی که شکمت بر تو دارد آن است که از آن به عنوان ظرفی برای جمع شدن حـرام چه کم باشد یا زیاد استفاده نکنی.\nوَ أَنْ تَقْتَصِدَ لَهُ فِی الْحَلاَلِ وَ لاَ تُخْرِجَهُ مِنْ حَدِّ التَّقْوِیَهِ اِلَى حَدِّ التَّهْوِینِ\nبلکه حتی در خوراکی های حلال نیز حـد اعتـدال را کاملا رعایت کن و برای تقویت از خوراک استفاده کن.\nفَاِنَّ الشِّبَعَ الْمُنْتَهِیَ بِصَاحِبِهِ اِلَى التُّخَمِ مَکْسَلَه وَ مَثْبَطَه\nزیرا که نتیجه ی پرخوری تنبلی و کسالت است.\nوَ مَقْطَعَه عَنْ کُلِّ بِر وَ کَرَم\nو تو را از خیر و صلاح و نیکوئی و انجام اعمال صالحه باز میدارد.\nوَ اِنَّ الرَّیَّ الْمُنْتَهِیَ بِصَاحِبِهِ اِلَى السُّکْرِ مَسْخَفَه وَ مَجْهَلَه وَ مَذْهَبَه لِلْمُرُوَّهِ\nچنانکه نتیجهء زیاده روی در نوشیدن مایعات نیز سخافـت و جهالت و بی عقلی خواهد بود .\n📕 در کتاب الهی نامه علامه حسن زاده آملی آمده است:\nالهی آزمودم تا شکم دائر است،\nدل بائر است.\nاللهم لا تجعل الدنیا اکبر همّنا","بخش دوم\nمتن:\nوَ كَانَ أَكْثَرَ دَهْرِهِ صَامِتاً، فَإِنْ قَالَ بَذَّ الْقَائِلِينَ وَ نَقَعَ غَلِيلَ السَّائِلِينَ، وَ كَانَ ضَعِيفاً مُسْتَضْعَفاً، فَإِنْ جَاءَ الْجِدُّ فَهُوَ لَيْثُ غَابٍ وَ صِلُّ وَادٍ، لَا يُدْلِي بِحُجَّةٍ حَتَّى يَأْتِيَ قَاضِياً\nترجمه:\nبيشتر اوقات زندگانى اش ساكت بود و (در عين حال) اگر سخنى مى گفت بر گويندگان چيره مى شد و عطش سؤال كنندگان را فرو مى نشاند.\n(به دليل نهايت تواضع بر حسب ظاهر) انسان ضعيفى بود و مردم نيز او را ضعيف مى شمردند؛ ولى هرگاه كار مهم و جدى به ميان مى آمد همچون شير بيشه مى خروشيد و مانند مار بيابانى به حركت درمى آمد. پيش از حضور در مجلس داورى، دليلى اقامه نمى كرد.\nتفسیر:\n💠 کَانَ لِی فِیمَا مَضَى أَخٌ فِی اللَّهِ، وَ کَانَ [یُعَظِّمُهُ] یُعْظِمُهُ فِی عَیْنِی صِغَرُ الدُّنْیَا فِی عَیْنِهِ، وَ کَانَ خَارِجاً مِنْ سُلْطَانِ بَطْنِهِ، فَلَا یَشْتَهِی مَا لَا یَجِدُ وَ لَا یُکْثِرُ إِذَا وَجَدَ\n🔵خلاصه بخش اول:\nمن در گذشته برادرى الهى و دینى داشتم که وصفش چنین بود.\nآنچه او را در نظرم بزرگ جلوه مى داد این بود که دنیا در نظر او کوچک بود.\nسلطان شکم نبود\n💠وَکَانَ أَکْثَرَ دَهْرِهِ صَامِتاً\nبیشتر اوقات زندگانى اش ساکت بود.\n💠فَإِنْ قَالَ بَذَّ الْقَائِلِینَ\nدر عین حال اگرسخنى مى گفت بر گویندگان چیره مى شد، و پیشی می گرفت[بَذَّ]\n💠 وَنَقَعَ غَلِیلَ السَّائِلِینَ\nو تشنگی وعطش [غَلِیلَ] سؤال کنندگان را فرو مى نشاند. و انان را سیراب می کرد [نَقَعَ]\n🔻سومین صفت برادران علی🔻\n🟢 در سومین وصف حضرت مى فرماید: برادران من کسانی هستند که هرگاه سخن بگویند گزیده و حساب شده است به گونه اى که همه مستمعین را بهره مند مى سازند و عطش آنها را فرو مى نشانند.\n⏪ خود این وصف نیز از سه بخش تشکیل شده است:\n◀️الف. وَکَانَ أَکْثَرَ دَهْرِهِ صَامِتاً\nاکثر اوقات ساکت بود\nراوی میگوید:\nدخلتُ على الرضا علیه السلام ··· فَوَعَظَنا\nخدمت امام رضا علیه السلام وارد شدیم، حضرت ما را موعظه کرد و فرمود:\nثمَّ قالَ : إنّ العابِدَ مِن بَنی إسرائیلَ لَم یَکُن عابِدا حتّى یَصمُتَ عَشرَ سِنینَ ، فإذا صَمَتَ عَشرَ سِنینَ کانَ عابِدا\nعابد بنى اسرائیل عابد نمى شد تا اینکه ابتدا دَه سال خاموشى اختیار مى کرد و هرگاه دَه سال دم فرو مى بست، آنگاه عابد مى شد.\nاگر کسی میخواهد به مقام عبادت برسد باید قبلش دوره ی سکوت بگذراند.\nزبان خود را کنترل کند که دروغ نگوید، غیبت نکند، استهزاء نکند، حرف کم ارزش نزند، حرف غیر علمی نزند، مشاوره اشتباه ندهد، فحاشی نکند و…\n🟢سخن انسان باید ذکر الهی باشد.\nپیامبر صلی الله علیه واله فرمود:\nلا تُکثِرُوا الکلامَ بغَیرِ ذِکرِ اللّه ِ\nدر غیر از ذکر خدا، زیاده گویى نکنید ؛\nفإنَّ کَثرَهَ الکلامِ بغَیرِ ذِکرِ اللّه ِ قَسوَهُ القَلبِ\nزیرا زیاده گویى در غیر ذکر خدا، موجب سخت دلى مى شود،\nإنّ أبعَدَ الناسِ مِن اللّه ِ القَلبُ القاسی\nو دورترین مردم از خدا، سختدل است.\nذکر معنای گسترده ای دارد از نماز و قرآن گرفته تا ذکر مصطلح را شامل میشود. انسان باید کلام های زائد را قطع کند و به ذکر الهی مشغول باشد.\n🔴مقصود از سکوت، رفتن در هپروت نیست.\nمقصود از سکوت، ساکن شدن ظاهری و فرو رفتن در تخیلات و توهمات نیست.\nچون خود آن تخیل و توهم آفت زا و مشکل آفرین است.\nسکوت اگر برای حل مشکل باشد، برای تفکر و اندیشه و اصلاح باشد خوب است.\nسکوتی که در آن فکر نباشد غفلت است.\nامام کاظم علیه السلام فرمود :\nدَلِیلُ‏ الْعَقْلِ‏ التَّفَکُّرُ وَ دَلِیلُ التَّفَکُّرِ الصَّمْتُ هر چیزى را راهنمایى است و راهنماى عقل اندیشیدن است و راهنماى اندیشیدن خاموشى است.\nانسان تا به خاموشی نرسد، فرصت برای تفکر پیدا نکرده است. باید سکوت انسان تفکر ساز باشد نه اینکه سکوت کند تا در خیالات و توهمات فرو برود.\nامیرالمومنین علیه السلام فرمود:\nکلُّ سُکوتٍ لَیسَ فیهِ فِکْرَهٌ فهُوَ غَفلَهٌ\nهر سکوتى که با اندیشیدن همراه نباشد غفلت است.\n◀️ب. فَإِنْ قَالَ بَذَّ الْقَائِلِینَ\nاگر صحبت میکرد، همه را ساکت میکرد\nسکوت مطلق خوب نیست، انسان باید توانایی سخن گفتن در موقع نیاز را داشته باشد. اگر جایی شبهه ای مطرح شد، یا حقی ناحق شد انسان باید توان سخن گفتن و اقناع دیگران را داشته باشد.\nامیرالمومنین فرمود :\nکُن صَموتاً مِن غَیرِ عِیٍّ\nخاموش باش ، نه از روى درماندگى.\nالقَولُ بِالحَقِّ خَیرٌ مِن العِیِّ و الصَّمتِ سخن گفتنِ به حق ، بهتر است از درماندن و خاموشى .\nدر حکمت ۱۸۲ فرمود:\nلَا خَیْرَ فِی الصَّمْتِ عَنِ الْحُکْمِ،\nخاموش ماندن از گفتار حکمت آمیز فایده اى ندارد .\nکَمَا أَنَّهُ لَا خَیْرَ فِی الْقَوْلِ بِالْجَهْلِ\nهمان گونه که سخن گفتن نابخردانه بی فایده است.\n🟢یک نمونه از پاسخ های حکیمانه:\nراوی میگوید: در مسجد النبی در مدینه در کنار امام کاظم نشسته بودیم و در مورد زنان گفت وگو مى‌کردیم و بسیار در موردشان سخن گفتیم.\nوَ هُوَ سَاکِتٌ لاَ یَدْخُلُ فِی حَدِیثِنَا بِحَرْفٍ ولى آن حضرت ساکت بود تا ما سخن مى‌گفتیم حتّى یک کلمه چیزى نفرمود. فَلَمَّا سَکَتْنَا قَالَ…\nفرمود:\n+ زن خوب زنی است که تو به او اشتیاق داشته باشى و او نیز عقل و ادب داشته باشد و نیاز نداشته باشد که امر و نهى کنى و خودش وظیفه‌هایش را تشخیص بدهد.\n+ در درجۀ پایین‌تر زنی است که تو او را مى‌خواهى ولى ادب ندارد و تو محتاج به دستور دادن و بازداشتن او هستى.\nوَ دُونَهَا مَا کَانَ لَکَ فِیهَا هَوًى وَ لَیْسَ لَهَا عَقْلٌ وَ لاَ أَدَبٌ فَتَصْبِرُ عَلَیْهَا لِمَکَانِ هَوَاکَ فِیهَا\n+ ازاین پایین‌تر آن زنی است که تو او را مى‌خواهى، ولى او عقل و ادب ندارد، ولى به خاطر اشتیاقى که به او دارى او را تحمّل مى‌کنى.\n+ ولی زنی که نه تو او را مى‌خواهى چون زیبا نبست ، و نه عقل و ادب دارد، از این زن به اندازه اقیانوسی فاصله بگیر.\nقَالَ فَأَخَذْتُ بِلِحْیَتِی … لِمَا لَمْ نَقُمْ فِیهِ عَلَى شَیْءٍ وَ لِجَمْعِهِ اَلْکَلاَمَ\nراوى گوید: من ریش خود را به‌دست گرفتم و درفکز فرو رفتم چرا که ما این‌همه در این مورد بحث کردیم، ولى به جایى نرسیدیم، ولى آن حضرت تمام مطلب را با سخنى جامع و کامل بیان فرمود.\n🔴مومن باید دستش از استدلال پر باشد.\nدر زیارت جامعه کبیره که مستحب است در حرم اهل بیت خوانده شود خدمت امام عرض میکنیم:\nمُحَقِّقٌ لِمَا حَقَّقْتُمْ، مُبْطِلٌ لِمَا أَبْطَلْتُمْ\nمن حق مى دانم و محققانه میتوانم اثبات کنم آن چه را شما حق دانستید و اثبات کردید و باطل مى دانم و رد میکنم آن چه را شما باطل دانستید و رد کردید.\nاین محکم و مستدل حرف زدن است که حرف انسان را مقبول میکند.\n❌فحش جای استدلال را نمی گیرد.\nدر خطبه ۲۰۶ وقتی معاویه شریعه فرات را تصرف کرد، برخی از یاران حضرت فحاشی میکردند حضرت فرمود:\nإِنِّی أَکْرَهُ لَکُمْ أَنْ تَکُونُوا سَبَّابِینَ\nمن خوش ندارم که شما دشنام دهنده باشید؛\nوَ لَکِنَّکُمْ لَوْ وَصَفْتُمْ أَعْمَالَهُمْ وَ ذَکَرْتُمْ حَالَهُمْ کَانَ أَصْوَبَ فِی الْقَوْلِ\nامّا اگر کردار معاویه را یادآور مى‌شدید و گمراهی‌ها و کارهاى ناشایسته آنان را بر مى‌شمردید، به صواب نزدیک‌تر\nوَ أَبْلَغَ فِی الْعُذْر\nو در عذرپذیری رساتر بود‌،\nبه‌جاى دشنام آنان بهتر بود، مى‌گفتید: خدایا خون ما و آن‌ها را حفظ کن،\n◀️ج. قَالَ بَذَّ الْقَائِلِینَ وَنَقَعَ غَلِیلَ السَّائِلِینَ\nسخن باید تشنگی را برطرف کند.\nنوع حرف زدن و پاسخ دادن باید با نحوی باشد که مشکل را حل کند، نیاز مخاطب را بر آورده کند، بتواند نیاز علمی مخاطب را پاسخ گوید.\nاینکه مخاطب دانسته های خود را بدون توجه به نیاز مخاطب و عطش او بیان کند، با روش و مسیر برادران امیرالمومنین موافق و همراه نیست.\n⏪نهج البلاغه آب گوارایی است بر جگر تشنگان حقیقت.\nفرمایشات امیرالمومنین در بخش خطبه ها و نامه ها و حکمت ها، چه آنجایی که با خدا مناجات مبکند، چه آنجایی که با دوستان صحبت میکند، چه آنجایی که با مخالفین احتجاج میکند، چه در وقت فریاد زدن بر سر تنبل ها، چه وقتی که از مرگ و قیامت صحب میکند، چه آنجایی که سیمای حکومت اسلامی را به تصویر میکشد و…. همه و همه بر طرف کننده تشنگی مشتاقان حقیقت است.\n🟢در خطبه ۱۵۶در مورد قرآن فرمود: عَلَیْکُمْ بِکِتَابِ اللَّهِ، فَإِنَّهُ الْحَبْلُ الْمَتِینُ\nکتاب خدا را محکم بگیرید; چرا که رشته اى است مستحکم\nوَ النُّورُ الْمُبِینُ وَ الشِّفَاءُ النَّافِعُ\nو نورى است آشکار; شفابخش و پرمنفعت و سیراب کننده،\nوَ الرِّیُّ النَّاقِعُ\nو فرو نشاننده عطش تشنگان حقّ است.\n🟢 خود حضرت فرمود من قرآن ناطق ام. در خطبه ۱۸۵ فرمود:\nذَلِکَ الْقُرْآنُ، فَاسْتَنْطِقُوهُ وَ لَنْ یَنْطِقَ وَ لَکِنْ أُخْبِرُکُمْ عَنْهُ\nاین کتاب همان قرآن است. آن را به سخن آرید تا همه چیز را بازگو کند; هر چند هرگز براى شما نسبت به تمام این امور سخن نمى گوید; ولى من از جانب او به شما خبر مى دهم.\nوقتی قرآن صامت سیراب کننده عطش تشنگان است، قرآن ناطق امیرالمومنین نیز سیراب کننده عطش مشتاقات حق و حقیقت است.\n↙️ نکاتی در مورد سکوت:\nآیت الله جوادی: در اسلام اصل بر سکوت است مگر آنکه انسان دلیلی داشته باشد برای حرف زدن.\nدر حکمت ۶۰ فرمود :\nاَللِّسانُ سَبُعٌ إِن خُلِّىَ عَنهُ عَقَرَ\nزبان درنده اى است که اگر رها شود، گاز مى گیرد.\nاگر انسان مراقب نباشد و هر حرفی بزند و سکوت را بشکند، این حیوان درنده هم به دیگران آسیب میزند هم به خود او.\n↙️ خواری انسان گاهی از طریق حرفهایش ایجاد میشود.\nامام صادق علیه السلام فرمودند :\nإِذا أَرادَ اللّه بِعَبدٍ خِزیا أَجرى فَضیحَتَهُ عَلى لِسانِهِ\nهرگاه خداوند بخواهد بنده اى را رسوا کند، از طریق زبانش او را رسوا مى کند.\n↙️سخن را مثل دارو استفاده کنید.\nامیرالمومنین علیه السلام :\nالکَلامُ کالدَّواءِ قَلیلُهُ یَنفَعُ وَ کَثیرُهُ یُهلِکُ سخن چون دوا است، اندکش سودمند و زیادش کشنده است.\n📗در رساله حقوق امام سجاد علیه السلام آمده است :\nحَقُّ اللِّسانِ إِکرامُهُ عَنِ الخَنى\nحق زبان، دور داشتن آن از زشت گویى،\nوَ تَعویدُهُ الخَیرَ\nعادت دادنش به خیر و خوبى،\nوَ تَرک الفُضولِ\nترک گفتار بى فایده،\nالَّتى لافائِدَهَ لَها وَ البِرُّ بِالنّاسِ\nو نیکى کردن زبانی به مردم\nوَ حُسنُ القَولِ فیهِم\nو خوشگویى درباره آنان است.\n🔻چهارمین صفت برادران علی🔻\n💠کَانَ لِی فِیمَا مَضَى أَخٌ فِی اللَّه…\nوَکَانَ ضَعِیفاً مُسْتَضْعَفاً\nبه دلیل نهایت تواضع بر حسب ظاهر انسان ضعیفى بود و مردم نیز او را ضعیف مى شمردند.\n💠 فَإِنْ جَاءَ الْجِدُّ فَهُوَ لَیْثُ غَابٍ وَ صِلُّ وَادٍ\nولى هرگاه کار مهم وجدى به میان مى آمد همچون شیر بیشه مى خروشید و مانند مار افعی بیابانى به حرکت درمى آمد.\n🟢در چهارمین وصف حضرت مى فرماید: برادر من کسی بود که اهل نمایش و غرور نبود، خود را به رخ دیگران نمی کشید و چه بسا از جهت ظاهری نیز ضعیف بود ولی او قدرت نهفته ای داشت که در لحظات سخت و جدی بروز پیدا میکرد. مانند شیر بیشه می غرید ،\nو مانند افعی از این سو به آن سوی میدان حرکت میکرد و کل میدان را تحت نظر داشت.\n🔴 برادران امیرالمومنین کسانی هستند که اهل پرخوری نیستند، اهل نمایش و اظهار قدرت نیستند، جسم نحیفی دارند، از جهت جسمی شاید ضعیف به نظر برسند ولی به هیچ وجه از روی قلدری و غرور اهل ظالم نیستند.\nبه تعبیر جناب حافظ:\nمن از بازوی خود دارم بسی شکر/\nکه زور مردم آزاری ندارم.\n⏪ مستضعف به چه معناست؟!\nقرآن کریم در مورد وارثین زمین میفرماید: 《وَنُرِیدُ أَنْ نَمُنَّ عَلَى الَّذِینَ اسْتُضْعِفُوا فِی الْأَرْضِ وَنَجْعَلَهُمْ أَئِمَّهً وَنَجْعَلَهُمُ الْوَارِثِینَ؛ قصص – ۵》\nو ما اراده داشتیم که بر آن طایفه ضعیف و ذلیل کرده شده در آن سرزمین منّت گذارده و آنها را پیشوایان (خلق) قرار دهیم و وارث (ملک و جاه فرعونیان) گردانیم.\n↙️ ضعیف اگر به باب استفعال برود و از آن اسم مفعول ساخته شود، میشود مستضعف.\nمستضعفین یعنی کسانی که بالقوه قوی هستند، توانمندند ولی فعلا شرایط ظهور و بروز آن توانمندی حاصل نشد.\n+ برادران حضرت کسانی هستند که دشمن میخواهد آنان را تضعیف کند. دشمن به خاطر پتانسیل و قدرتی که آنها دارند، میخواهند آنان را تضعیف کنند ولی غافل از اینکه این نیرو و قدرت در زمان لازم ظهور و بروز پیدا میکند.\n+ برادران امیرالمومنین همین بسیجی هایی هستند که کسی روی قدرت آنها حساب باز نمیکرد ولی وقتی پای چنگ به این کشور باز شد، هشت سال مقابل کل دنیا ایستادند.\n+برادران امیرالمومنین جوانهایی بودند که خیلی ها خیال میکردند اینها دنیا زده شده اند و جوان امروزی هستند و توان کار ندارند، ولی وقتی دفاع از حرم پیش آمد ریشه داعش را خشکاندند.\n+ برادران امیرالمومنین یمنی ها و یمانی هایی هستند که مردم دنیا آنها را اصلا به حساب نمی آوردند و آنها را مردمی جنگ زده و پا برهنه حساب میکردند، ولی موقعیت مبارزه با اسرائیل که فراهم شد، همه دیدند که چگونه یکی از مهمترین مسیرهای آبی جهان را بر روی دشمنان خدا بستند و آنها را به ذلت کشاندند.\n+ مومنین شاید از جهت ظاهری ضعیف باشند ولی روحیه و انگیزه و پتانسیلی که در اینها هست بیش از فکر و اندیشه ی دشمنان است\n📗مرحوم مقنیه میفرماید:\nبرادران امیرالمومنین کسانی هستند که: زَاهِداً مُتَوَاضِعاً یَحْسَبُهُ الْجَاهِلُ مِن اهلِ القِلَّهِ وَ الذِّلِّهِ\nبردران کسانی هستند زاهد متواضع که جاهلان گمان می کنند مردمان ذلیل هستند.\nوَ لَکِنَّهُ إِنْ جاءَ الجِدُّ یَحمِی حَوْزَتَهُ وَ یَصُونُ کَرَامَتَهُ\nولیکن وقتی زمان تلاش باشد در همان حوزه حمایتگر شجاع و کرامت را حفظ می کردند.\nوَ یُسَخِّی بِنَفْسِهِ فِی سَبِیلِ اَلْحَقِّ وَ اَلاِنْسَانِیهْ\nدر راه حق و انسانیت سخاوت بخرج می دادند\n🟢علی علیه السلام، برادر مستضعفان است.\nپیامبر به امیرالمومنین فرمود:\nیَا عَلِیُّ إِنَّ اَللَّهَ وَهَبَ لَکَ حُبَّ اَلْمَسَاکِینِ وَ اَلْمُسْتَضْعَفِینَ فِی اَلْأَرْضِ\nاى على،خداوند،دوستى و محبّت بینوایان و ضعیفان در زمین را به تو بخشیده است.\nفَرَضِیتَ بِهِمْ إِخْوَاناً وَ رَضُوا بِکَ إِمَاماً\nتو به برادرى با آنها راضى شدی، و آنها به امامت و پیشوایى تو خشنود شدند. فَطُوبَى لِمَنْ أَحَبَّکَ وَ وَیْلٌ لِمَنْ أَبْغَضَکَ پس خوشا به حال کسى که تو را دوست مى‌دارد و تصدیقت مى‌کند و واى بر کسى که با تو دشمن است و تکذیبت مى‌نماید.\n🔴حافظ در وصف چنین برادرانی میگوید:\nشاه منصور واقف است که ما/\nروی همّت به هر کجا که نهیم\nدشمنان را زخون کفن سازیم /\nدوستان را قبای فتح دهیم\nرنگ تزویر پیش ما نبود /\nشیر سُرخیم و افعی سِیَهیم\n🟢به امیرالمومنین هم میگفتند شما ضعیف هستی.\nحضرت در نامه ۴۵ فرمود :\nکَأَنِّی بِقَائِلِکُمْ یَقُولُ\nگویى یکى از شما را مى بینم که مى گوید،\nإِذَا کَانَ هَذَا قُوتُ ابْنِ أَبِی طَالِبٍ فَقَدْ قَعَدَ بِهِ الضَّعْفُ عَنْ قِتَالِ الْأَقْرَانِ\nاگر قوت پسر ابو طالب چنین است، باید که ناتوانیش از پاى بیفکند و از نبرد با هماوردان و کوشیدن با دلیران بازش دارد.\nوَ مُنَازَلَهِ الشُّجْعَانِ\nو کوشیدن با دلیران بازش دارد.\nأَلَا وَ إِنَّ الشَّجَرَهَ الْبَرِّیَّهَ أَصْلَبُ عُوداً\nبدانید، که آن درخت که در بیابانها پرورش یافته، چوبى سخت تر دارد.\nوَ الرَّوَاتِعَ الْخَضِرَهَ أَرَقُّ جُلُودا\nو بوته هاى سرسبز و لطیف، پوستى بس نازک. آرى، درختان بیابانى را به هنگام سوختن، شعله نیرومندتر باشد و آتش بیشتر.\nمن و رسول خدا، مانند دو شاخه ایم که از یک تنه روییده باشند و نسبت به هم چون ساعد و بازو هستیم. \n🔻پنجمین صفت برادران علی🔻\n💠کَانَ لِی فِیمَا مَضَى أَخٌ فِی اللَّهِ….\nفَإِنْ جَاءَ الْجِدُّ فَهُوَ لَیْثُ غَابٍ وَ صِلُّ وَادٍ\nلا یُدْلِی بِحُجَّهٍ حَتَّى یَأْتِیَ قَاضِیاً\nپیش از حضور در مجلس داورى، دلیلى اقامه نمى کرد.\n[«یُدْلِى» از ماده «ادلاء» در اصل به معناى فرستادن دلو در چاه براى کشیدن آب است و به معناى اقامه دلیل در نزد قاضى نیز استعمال شده است.]\n🟢با توجه به اینکه در دوران مورد نظر و بعد از زمان رسول الله حکومت به دست خلفا افتاد، امیرالمومنین میفرماید او ( برادر من) برای احقاق حق، نزد حاکمان و قاضیان حکومت ظلم نمیرفت.\n❌رفتن پیش قاضی حکومت ظالم حرام است.\nمرحوم کلینی در کافی نقل میکند:\nسَأَلْتُ أَبَا عَبْدِ اللَّهِ ع- عَنْ رَجُلَیْنِ مِنْ أَصْحَابِنَا بَیْنَهُمَا مُنَازَعَهٌ فِی دَیْنٍ أَوْ مِیرَاثٍ\nاز امام صادق پرسیدم: دو نفر از ما شیعیان نزاعی دارند،\nفَتَحَاکَمَا إِلَى السُّلْطَانِ وَ إِلَى الْقُضَاهِ أَ یَحِلُّ ذَلِکَ\nپس به نزد سلطان یا قاضیان حکومت‏های جور جهت حل آن می‏روند؛ آیا این عمل جایز است؟\nقَالَ مَنْ تَحَاکَمَ إِلَیْهِمْ فِی حَقٍّ أَوْ بَاطِلٍ فَإِنَّمَا تَحَاکَمَ إِلَى الطَّاغُوتِ\nحضرت فرمود: هر کس در موارد حق یا باطل به آنان مراجعه کند؛\nوَ مَا یَحْکُمُ لَهُ فَإِنَّمَا یَأْخُذُ سُحْتاً وَ إِنْ کَانَ حَقّاً ثَابِتاً\nدر واقع به سوی طاغوت رفته و از او مطالبه قضاوت کرده است.\nلِأَنَّهُ أَخَذَهُ بِحُکْمِ الطَّاغُوتِ وَ قَدْ أَمَرَ اللَّهُ أَنْ یُکْفَرَ بِهِ\nاز این رو آنچه بر اساس حکم او که خود فاقد مشروعیت است دریافت می‏دارد، به باطل اخذ نموده است؛ هر چند در واقع حق ثابت او باشد؛ زیرا آن را بر اساس حکم طاغوت گرفته است.\nقَالَ اللَّهُ تَعَالَى: یُرِیدُونَ أَنْ یَتَحاکَمُوا إِلَى الطَّاغُوتِ‏ وَ قَدْ أُمِرُوا أَنْ یَکْفُرُوا بِه‏\nخداوند امر فرموده است: باید به طاغوت کافر باشند و آن را به رسمیت نشناسند.\n🟢ابوذر و مقابله با طاغوت حتی بعد از مرگ:\nلَمَّا حَضَرَتْ أَبَا ذَرٍّ الْوَفَاهُ وَ هُوَ بِالرَّبَذَهِ- بَکَتْ زَوْجَتُهُ أُمُّ ذَرٍّ\nهنگامی که مرگ ابوذر در ربذه نزدیک شد همسرش امّ ذر گریست.\nقَالَتْ فَقَالَ لِی مَا یُبْکِیکِ\nاو گفت : چراگریه می کنی؟\nفَقَالَتْ مَا لِی لَا أَبْکِی وَ أَنْتَ تَمُوتُ بِفَلَاهٍ مِنَ الْأَرْضِ وَ لَیْسَ عِنْدِی ثَوْبٌ یَسَعُکَ کَفَناً\nگفتم: چطور گریه نکنم وقتی تو( ابوذر) در بیابانی میمیری و من جامه هایی ندارم که به جای کفن تو را بپوشاند.\nابوذر گفت: روزی پیامبر جمعی از ما را بشارت داد که از میان شما فردی در بیابان میمیرد و مومنین او را کفن میکنند.\nناگهان جمعی در بیایان به ابوذر و همسرش میرسند و ابوذر خطاب به آنها میگوید:\nوَ لَوْ کَانَ عِنْدِی ثَوْبٌ یَسَعُنِی کَفَناً لِی أَوْ لِامْرَأَتِی لَمْ أُکَفَّنْ إِلَّا فِی ثَوْبٍ لِی أَوْ لَهَا\nاگر جامه ای داشتم که کفنی برای من یا زنم باشد جز در جامه خودم یا جامه او کفن نمی شدم.\nوَ إِنِّی أَنْشُدُکُمُ اللَّهَ أَنْ لَا یُکَفِّنَنِی رَجُلٌ مِنْکُمْ کَانَ أَمِیراً أَوْ عَرِیفاً أَوْ بَرِیداً أَوْ نَقِیباً\nمن شما را به خدا قسم می دهم که کسی از میان شما اگر مسولیتی در حکومت ظالم داشته یا نامه رسان یا نگهبان بوده در غسل و کفن من مشارکت نکند\nام ذر گفت: در بین آن ها کسی نبود که مرتکب برخی از آنچه ابوذر گفته بود نشده باشد ، مگر جوانی از انصار که به ابوذر گفت: ای عمو من تو را در این عبا و دو جامه ای که در بقچه دارم و مادرم بافته است کفن می کنم.\nابوذر گفت: تو مرا کفن کن. سپس جان به جان آفرین تسلیم کرد و آن مرد انصاری او را کفن کرده و با کسانی که نزدش بودند او را غسل داد و بر او نماز خواندند و با گروهی که همگی اهل یمن بودند دفنش کردند.\nآن شخص مالک اشتر بود.\n💠لا یُدْلِی بِحُجَّهٍ حَتَّى یَأْتِیَ قَاضِیاً\nپیش از حضور در مجلس داورى، دلیلى اقامه نمى کرد.\n◀️ ب. دعوا را پیش مردم نمی برد، فقط در پیش قاضی حرف میزند\nاشاره به اینکه اگر حقى را مى خواست از دیگرى بگیرد، جار و جنجال به راه نمى انداخت و زمین و آسمان را از فریاد خود پر نمى ساخت فقط بعد از حضور در محضر قاضى دلیل خود را ارائه مى کرد. به تعبیر دیگر او پیوسته تابع قانون شرع بود و چیزى ماوراى قانون خدا از کسى نمى طلبید.\n🟢به شخصی گفتند با همسرت چه مشکلی داری که میخواهی او را طلاق دهی؟\nگفت شما انتظار دارید من در مورد ناموسم با شما حرف بزنم؟!!!\nمدتی گذشت و به او گفتند چه شد که آن زن را طلاق دادی؟\nگفت شما انتظار دارید من در مورد ناموس دیگران حرف بزنم؟!\n🔴 روحیه جار و جنجال و استفاده از احساسات مردم برای نشاندن حرف خود به کرسی، روحیه خوبی نیست. یاران و برادران امیرالمومنین اهل جار و جنجال در امور شخصی نیستند.\nمومنین باید روحیه خویشتن داری و گذشت داشته باشند و از اینکه بخواهند با سر و صدا به حق خودشان برسند پرهیز کنند چه برسد به اینکه بخواهند با سر و صدا ناحقی را بگیرند.\nالبته شاید در شرایط خاصی نیاز به این کار باشد، مثلا حقی اجتماعی ضایع شده و… ولی داشتن این روحیه زیبنده نیست.\n◀️ج. استدلال را برای هر کسی اقامه نمیکرد.\nاگر چه استدلالی حرف زدن بسیار لازم و ضروری است. ولی هر کسی استدلال را نمی فهمد، هرکسی صلاحیت این را ندارد با او مستدل حرف زدن.\n🔴امیرالمومنین به معاویه میگوید من تو را لایق جواب دادن و استدلال اقامه کردن نمی بینم ولی اگر حرفی میزنم و اقامه دلیل میکنم برای این است که بعدها اگر انسان های حق طلبی بودند ببینند حق با چه کسی بود.\n📗 در حکمت ۳۱۷ یک یهودی به حضرت عرض کرد:\nمَا دَفَنْتُمْ نَبِیَّکُمْ حَتَّى اخْتَلَفْتُمْ فِیهِ\nشما هنوز پیامبرتان را دفن نکرده بودید درباره اش اختلاف کردید!\nفَقَالَ (علیه السلام) لَهُ:\nإِنَّمَا اخْتَلَفْنَا عَنْهُ لَا فِیهِ\nما درمورد جانشینی او اختلاف کردیم، نه درباره حقانیت و نبوت خودش،\nوَ لَکِنَّکُمْ مَا جَفَّتْ أَرْجُلُکُمْ مِنَ الْبَحْرِ حَتَّى قُلْتُمْ لِنَبِیِّکُمْ “اجْعَلْ لَنا إِلهاً کَما لَهُمْ آلِهَهٌ، اما شما پس از عبور از دریا و غرق شدن فرعونیان هنوز پاهایتان خشک نشده بود به پیامبر خود گفتید: براى ما هم بتى بساز همانگونه که این قوم بت پرست بت هایى دارند.\nقالَ إِنَّکُمْ قَوْمٌ تَجْهَلُونَ”\nو موسى به شما گفت: شما مردم نادانى هستید که بعد از این همه معجزات الهى در توحید شک مى کنید.\nاینجا دیگر حضرت برای یهودی استدلال نمی آورد بلکه با یاد آوری یک واقعه به او میفرماید شما چه میگویید که هنوز خدا را قبول ندارید بعد آمده اید در مورد پیامبر ما اظهار نظر کنید..\nاللهم الحقنا بالصالحین","بخش سوم \nمتن:\nوَ كَانَ لَا يَلُومُ أَحَداً عَلَى مَا يَجِدُ الْعُذْرَ فِي مِثْلِهِ حَتَّى يَسْمَعَ اعْتِذَارَهُ، وَ كَانَ لَا يَشْكُو وَجَعاً إِلَّا عِنْدَ بُرْئِهِ، وَ كَانَ يَقُولُ مَا يَفْعَلُ وَ لَا يَقُولُ مَا لَا يَفْعَلُ، وَ كَانَ إِذَا غُلِبَ عَلَى الْكَلَامِ لَمْ يُغْلَبْ عَلَى السُّكُوتِ\nترجمه:\nهيچكس را نسبت به كارى كه انجام داده، در آنجا كه امكان داشت عذرى داشته باشد ملامت نمى كرد تا عذر او را بشنود. او هرگز از درد خود جز هنگام بهبودى شكايت نمى كرد. همواره سخنى مى گفت كه خود انجام مى داد و چيزى را كه انجام نمى داد نمى گفت. اگر در سخن گفتن مغلوب مى شد هرگز در سكوت، كسى بر او غلبه نمى يافت.\nتفسیر:\n💠کَانَ لِی فِیمَا مَضَى أَخٌ فِی اللَّهِ،\nاوصاف برادر الهی من در گذشته چنین بود.\n🔻ششمین وصف برادران علی🔻\n💠وَکَانَ لا یَلُومُ أَحَداً عَلَى مَا یَجِدُ الْعُذْرَ فِی مِثْلِهِ حَتَّى یَسْمَعَ اعْتِذَارَهُ\nبرادر علی وصف او چنین بود که هیچکس را ملامت نمیکرد در انجام کاری که میشد برای آن عذرى پیدا می کرد. تا وقتی عذر او را بشنود.\nحضرت وصف این برادر الهى خود را ملامت نکردن، عذر تراشیدن و فرصت دادن به طرف مقابل برای دفاع از خود میداند.\n🟢عذر تراشی برای همه مخصوصا عالم و عاقل:\nشتاب کردن در ملامت افراد کار عاقلانه اى نیست. چه بسا براى کار که انجام داده اند عذرى داشته اند که اگر انسان آن عذر را بشنود آنها را معذور مى دارد و از ملامتى که قبلاً کرده پشیمان مى شود و ناچار از عذرخواهى مى گردد،\nبنابراین چرا عجله کند و پیش از شنیدن عذر طرف، زبان به ملامت وسرزنش او بگشاید. به خصوص اگر اینگونه مسائل در مورد افراد عالم و عاقل و فهمیده باشد که احتیاط کردن بسیار سزاوارتر است.\nقرآن مجید در داستان حضرت خضر و موسى نشان داده که موسى علیه السلام در قضاوت عجله مى کرد وخضر را بر کارش سرزنش مى نمود ،\nاما هنگامى که عذر او را شنید دانست که آنچه انجام داده، حق و به فرمان خدا بوده است. و این قضاوت زودهنگام باعث فراق و جدایی از خضر شد.\n🔴در زندگی روزمره انسان اتفاقاتی می افتد که شاید باعث دلخوری یا سوء تفاهم و… شود. شریعت مقدس دو دستور متفاوت به هر کدام از طرفین داده است.\n↙️ به کسی که وعده کرده و قول انجام کاری را داده است میگوید کاری نکن که عذر بخواهی.\n📗در روایتی از امیرالمومنین که بخشی از آن در نامه ۳۳ نیز ذکر شده فرمود: إیّاکَ و ما تَعتَذِرُ مِنهُ ؛ فإنَّهُ لا یُعتَذَرُ مِن خَیرٍ\nبپرهیز از کارى که به سبب آن پوزش بخواهى؛ چرا که از کار خوب، پوزش خواهى نمى شود.\nدر حکمت ۳۲۹ فرمود :\nالاستِغناءُ عَنِ العُذرِ أعَزُّ مِنَ الصِّدقِ بِهِ نیاز نیافتن به پوزش خواهى، عزّت بخش تر از پوزش خواهى موجّه است .\n📕در نامه ۶۹ به حارث همدانی فرمود:\nو احذَرْ کلَّ عَمَلٍ إذا سُئلَ عَنهُ صاحِبُهُ أنکَرَهُ أوِ اعتَذَرَ مِنهُ\nبپرهیز از هر کارى که اگر از انجام دهنده آن درباره اش بازخواست شود، یا انکارش کند و یا پوزش خواهد.\nامام حسین علیه السلام فرمود :\nإیّاکَ و ما تَعتَذِرُ مِنهُ ؛\nزنهار از کارى که از آن پوزش بخواهى؛\nفإنَّ المُؤمِنَ لا یُسیءُ و لا یَعتَذِرُ ،\nزیرا مؤمن نه بدى مى کند و نه پوزش مى خواهد\nو المُنافِقَ کُلَّ یَومٍ یُسیءُ و یَعتَذِرُ\nو منافق هر روز بدى مى کند ،\nو پوزش مى طلبد.\nپس بر انسان لازم است که وظیفه اش را به بهترین نحو انجام دهد که هیچ نیازی به عذر خواهی و عذر تراشی و دروغ گویی برای ماست مالی کردن کار پیدا نشود.\n↙️به کسی که کارش انجام نشده یا سر قرار معطل شده میگوید عذر تراشی کن.\n🟢مانند کسی که حق به گردنت دارد، عذر دوست را بپذیر.\nدر نامه ۳۱ فرمود:\nاِحمِلْ نَفسَکَ مِن أخیکَ عِندَ صَرمِهِ عَلَى الصِّلَهِ\nاگر برادرت از تو گسست، تو خود را به او پیوند ده،\nو عِندَ جُرمِهِ عَلَى العُذرِ ؛\nو اگر گناهى کرد، عذرش را بپذیر؛\nو کأنَّهُ ذو نِعمَهٍ عَلَیکَ\nچندان که گویى تو غلام او هستى و او مولاى توست.\n🔴عاقل عذر پذیر است.\nامیرالمومنین علیه الیلام فرمود:\nأعقَلُ النّاسِ أعذَرُهُم لِلنّاسِ\nخردمندترین مردم، عذر پذیرترین آنها از مردم است.\nدر دعای ۳۸ صحیفه چنین آمده :\nاللّهُمَّ إنّی أعتَذِرُ إلَیکَ مِن مَظَلومٍ ظُلِمَ بِحَضرَتی فلَم أنصُرْهُ ···\nبار خدایا! از تو عذر مى خواهم اگر در حضور من به کسى ستم شده و من یاریش نکرده باشم\nو مِن مُسیءٍ اعتَذَر إلَیَّ فلَم أعذِرْهُ .\nو کسى به من بدى کرده و عذر خواسته است و من عذرش را نپذیرفته باشم.\nامام سجاد از امور مهمی به خدا پناه میبرد، کمک نکردن به مظلوم. نپذیرفتن عذر افراد.\n🟢نه تنها عذر را بپذیر، بلکه عذر تراشی کن.\nامیرالمومنین علیه السلام فرمودند:\nاِقبَلْ عُذرَ أخیکَ ،\nعذر برادرت را بپذیر،\nو إن لَم یَکُن لَهُ عُذرٌ فَالتَمِسْ لَهُ عُذرا\nو اگر عذرى نداشت برایش عذرى بتراش.\n🔻نکته:\nمقصود از پذیرش عذر یا عذر تراشی این نیست که کسی مدام خطا و اشتباه کند، وظیفه خودش را درست انجام ندهد و ما همیشه مامور به عذر تراشی برای او باشیم. مقصود آنجاست که شخصی در موقعیت خاصی، بنا بر اتفاق و گرفتاری یا فراموشی اگر خطایی مرتکب شده، آن خدا نادیده گرفته شود.\n🔻نکته:\n💠 وَکَانَ لا یَلُومُ أَحَداً عَلَى مَا یَجِدُ الْعُذْرَ فِی مِثْلِهِ حَتَّى یَسْمَعَ اعْتِذَارَهُ\nشنیدن عذر و اجازه حرف زدن خودش یک مرحله از اصلاح و درست شدن است. گاهی انسان به خاطر اتفاقی که افتاده اصلا اجازه حرف زدن به طرف مقابل نمیدهد. نه تنها عذر او را نمی شنود و به خطای خود پی نمیبرد؛ بلکه کینه ای در دل طرف مقابل ایجاد میکند که این اختلاف و دشمنی را دامنه دارتر میکند.\nحضرت درخطبه الغراء (خطبه 83) فرمود: جَعَلَ لَکُم أسماعا لِتَعِیَ ما عَناها\nخداوند به شما دو گوش داد تا آنچه را به آنها مربوط مى شود دریافت کنند .\n🟢رحمت الهی در شنیدن حرف حق است. در خطبه ۷۶ فرمود:\nرَحِمَ اللّه ُ امرَأً سَمِعَ حُکما فَوَعى\nخدا رحمت کند مردى را که سخن حکیمانه اى شنید و آن را پذیرفت .\nعادت کنید به خوب شنیدن. در همین باب هم درغرر الحکم فرمود:\nعَوِّدْ اُذُنَکَ حُسنَ الاستِماعِ\nگوش خود را به خوب شنیدن عادت ده\n🔻هفتمین صفت برادران علی🔻\n💠وَکَانَ لا یَشْکُو وَجَعاً إِلاَّ عِنْدَ بُرْئِهِ\nاو هرگز از درد خود شکایت نمیکرد مگر هنگامی که بهبودى پیدا کرده بود.\nهفتمین وصف برادران امیرالمومنین آن است که هنگام ابتلا به درد شکایت نمی کنند.\n🔴حکایت درد یا شکایت از درد؟\nوقتی انسان از دردها و نداری و کمبودها شکایت میکند، ناله میکند و فریادش بلند است؛ چنانچه ناله براى دوستان باشد سبب آزردگى خاطر آنها مى شود و اگر براى دشمنان باشد سبب شادى وشماتت آنها مى گردد.\nاما اگر به هنگام بهبودى باشد توأم با نوعى شکرگزارى است و به بیان دیگر حکایت است نه شکایت.\n🟢دوستان امیرالمومنین کسانی هستند که دردشان برای خودشان است\n“الْمُؤْمِنُ بِشْرُهُ فِی وَجْهِهِ وَ حُزْنُهُ فِی قَلْبِهِ”؛\nشادی مومن در صورت او ظاهر و حزن او در قلبش مخفی است.\nولی وقتی بیماری و بی پولی و دردشان گذشت و کسی گلایه ای کرد، ابراز ناراحتی کرد به او میگویند نگران نباش، ما هم همین مشکل ها را داشتیم ولی الحمدلله برطرف شد.\nبه جای اینکه دل مومنین را خالی کند و آنها را بترساند به آنها دلداری میدهد و قوت قلب دیگران میشود.\n📕مرحوم کلینى در کافی ابوابی در مورد ثواب بیماری و تحمل بر دردهای آن آورده است.\nدرد را باید با جان خرید.\nامام باقر علیه السلام فرمود :\nسَهَرُ لَیْلَهٍ مِنْ مَرَضٍ أَوْ وَجَعٍ أَفْضَلُ وَ أَعْظَمُ أَجْراً مِنْ عِبَادَهِ سَنَهٍ\nشبى از بیمارى و درد نخوابیدن، برتر و اجرش بزرگتر از یک سال عبادت است.\n🟢 بیماری برکات خودش را دارد، بیقراری نکن. خداوند تعالی میفرماید:\nإِذَا مَرِضَ الْمُؤْمِنُ أَوْحَى اللَّهُ عَزَّ وَ جَلَّ إِلَى صَاحِبِ الشِّمَالِ لَا تَکْتُبْ عَلَى عَبْدِی مَا دَامَ فِی حَبْسِی وَ وَثَاقِی ذَنْباً\nهرگاه مؤمن بیمار شود، خداوند عز و جل به فرشته دست چپ او وحى فرماید که براى بنده ام، تا زمانى که در بند من است، گناهى ننویس.\nوَ یُوحِی إِلَى صَاحِبِ الْیَمِینِ أَنِ اکْتُبْ لِعَبْدِی مَا کُنْتَ تَکْتُبُهُ فِی صِحَّتِهِ مِنَ الْحَسَنَاتِ\nو به فرشته دست راست او وحى مى فرماید که همان حسناتى را که در زمان سلامتى بنده ام مى نوشتى، برایش بنویس.\n❌شکایت کردن از درد، ممنوع:\nقَالَ اللَّهُ عَزَّ وَ جَلَّ مَنْ مَرِضَ ثَلَاثاً فَلَمْ یَشْکُ إِلَى أَحَدٍ مِنْ عُوَّادِهِ\nاگر کسی سه روزی بیمار شود ولی از بیماری به عیادت کنندگان شکایت نکند. أَبْدَلْتُهُ لَحْماً خَیْراً مِنْ لَحْمِهِ وَ دَماً خَیْراً مِنْ دَمِهِ\nگوشتی بهتر از گوشت خودش و خونی بهتر از خون خودش به او میدهم.\nفَإِنْ عَافَیْتُهُ عَافَیْتُهُ وَ لَا ذَنْبَ لَهُ\nاگر او را از بیماری عافیت دهم، گناهانش را میریزم.\nوَ إِنْ قَبَضْتُهُ قَبَضْتُهُ إِلَى رَحْمَتِی\nو اگر او با بیماری از دنیا برود، او را به جوار رحمت خودم میبرم.\n⁉️سوال\nگفتن چه حرفی، شکایت از بیماری است؟!\n📗مرحوم کلینی در کافی “بَابُ حَدِّ الشِّکَایَهِ” دارد.\nراوی به امام صادق میگوید:\nسُئِلَ عَنْ حَدِّ الشِّکَایَهِ لِلْمَرِیضِ\nسوال شد از امام که حد شکایت مریض در چیست؟!\nفَقَالَ إِنَّ الرَّجُلَ یَقُولُ حُمِمْتُ الْیَوْمَ وَ سَهِرْتُ الْبَارِحَهَ\nفرمود: شکایت آن نیست که شخص بگوید:دیشب بیمار شدم یا از شدّت مرض و رنج درد زیادى کشیدم.\nوَ قَدْ صَدَقَ وَ لَیْسَ هَذَا شِکَایَهً\nاین ها را راست میگوید و شکایت نیستند.\nوَ إِنَّمَا الشَّکْوَى أَنْ یَقُولَ قَدِ ابْتُلِیتُ بِمَا لَمْ یُبْتَلَ بِهِ أَحَدٌ وَ یَقُولَ لَقَدْ أَصَابَنِی مَا لَمْ یُصِبْ أَحَداً\nولکن شکایت آن است که مثلا بگوید:به درد یا مشکلى دچار گشته‌ام که دیگرى به آن مبتلا نگردیده است.\n🔻نکته:\nدر بیماری، افشای بیماری درست نیست، ولی گفتن درد به کسی که کاری از دستش بر می آید، یا دیدن او باعث نشاط بیمار میشود یا انسان امید به دعای او دارد ایرادی ندارد.\nاعلام بیماری به برادران دینی رجحان دارد.\nامام صادق علیه السلام فرمود:\nیَنْبَغِی لِلْمَرِیضِ مِنْکُمْ أَنْ یُؤْذِنَ إِخْوَانَهُ بِمَرَضِهِ فَیَعُودُونَهُ\nسزاوار است بیمارى که از شما شیعیان است، برادران خویش را باخبر کند تا از او عیادت کنند\nفَیُؤْجَرُ فِیهِمْ وَ یُؤْجَرُونَ فِیهِ …\nو عیادت‌کنندگانش به سبب او، و او به سبب آن‌ها از سوى خدا پاداشى گیرند.\n🟢برادران دینی دعای مستجاب دارند، بیماری را به آنها اطلاع دهید.\nامام کاظم علیه السلام فرمود:\nإِذَا مَرِضَ أَحَدُکُمْ فَلْیَأْذَنْ لِلنَّاسِ یَدْخُلُونَ عَلَیْهِ\nچون یکى از شما بیمار شود، باید به مردم اطّلاع دهد تا نزد او آیند؛\nفَإِنَّهُ لَیْسَ مِنْ أَحَدٍ إِلَّا وَ لَهُ دَعْوَهٌ مُسْتَجَابَهٌ\nچرا که هر فردى دعاى مستجابى دارد.\n🔻نکته:\nدر بحث بیماری مطالب زیادی قابل ذکر است. یک مطلب نگرانی و دلگیری افراد بیماری است که در ایام کسالت با خودشان فکر میکنند چقدر از اعمال و طاعات و برنامه های معنوی عقب افتاده اند و توان انجام برخی عبادات را ندارند.\nدر حالی که اگر انسان ادب و آداب بیماری را رعایت کند، خداوند نیز نوع معامله اش با بیمار به نحو دیگری است\n⏪ بشارتی برای پیران بیمار:\nپیامبر صلی الله علیه وآله فرمود :\nإِنَّ الْمُسْلِمَ إِذَا غَلَبَهُ ضَعْفُ الْکِبَرِ\nهرگاه ناتوانى و پیرى بر مسلمان چیره شود،\nأَمَرَ اللَّهُ عَزَّ وَ جَلَّ الْمَلَکَ أَنْ یَکْتُبَ لَهُ فِی حَالِهِ تِلْکَ مِثْلَ مَا کَانَ یَعْمَلُ وَ هُوَ شَابٌّ نَشِیطٌ صَحِیحٌ\nخداى متعال به فرشته فرمان مى‌دهد که آن چه را در دوران نشاط‍‌ جوانى و تندرستى انجام مى‌داده است، برایش بنویسد.\nوَ مِثْلَ ذَلِکَ إِذَا مَرِضَ وَکَّلَ اللَّهُ بِهِ مَلَکاً یَکْتُبُ لَهُ فِی سُقْمِهِ مَا کَانَ یَعْمَلُ مِنَ الْخَیْرِ فِی صِحَّتِهِ\nهم‌چنین هرگاه مسلمان بیمار شود، خداوند فرشته‌اى را بر او مى‌گمارد تا کارهاى خوبى را که در حال تندرستى انجام مى‌داده، براى او بنویسد،\nحَتَّى یَرْفَعَهُ اللَّهُ وَ یَقْبِضَهُ\nتا زمانى که خداوند او را بالا برده، قبض روح نماید.\nوَ کَذَلِکَ الْکَافِرُ إِذَا اشْتَغَلَ بِسُقْمٍ فِی جَسَدِهِ\nوهمینطور کافر هنگامی که به بیملری گرفتار شود.\nکَتَبَ اللَّهُ لَهُ مَا کَانَ یَعْمَلُ مِنَ الشَّرِّ فِی صِحَّتِهِ.\nخداوند فرشته‌اى را بر او مى‌گمارد تا کارهاى شر او را که در حال تندرستى انجام مى‌داده، براى او بنویسد،\n🔻هشتمین صفت برادران علی🔻\n💠وَ کَانَ یَقُولُ مَا یَفْعَلُ وَلا یَقُولُ مَا لا یَفْعَلُ\nهمواره سخنى مى گفت که خود انجام مى داد و چیزى را که انجام نمى داد نمى گفت.\n🟢حضرت در هشتمین وصف برادر خدایی اش مى فرماید: ظاهر و باطن او، قلب و زبان او یکی بود و دو رویی و دو زبانی نداشت.\nدر خطبه ۱۰۱ میفرماید:\nشَهَادَهً یُوَافِقُ فِیهَا السِّرُّ الْإِعْلَانَ وَ الْقَلْبُ اللِّسَانَ‏.\nگواهى مى دهیم که معبودى جز او نیست و محمّد برگزیده و فرستاده اوست گواهى و شهادتى که درون و برون، و قلب و زبان در آن هماهنگ باشد.\n🔴چرا انسان قلب و زبانش یکی نباشد، قول و فعلش یکی نباشد؟\nدرخطبه ۱۷۵ فرمود :\nأَیُّهَا النَّاسُ إِنِّی وَاللَّهِ مَا أَحُثُّکُمْ عَلَى طَاعَهٍ إِلاَّ وَأَسْبِقُکُمْ إِلَیْهَا وَلا أَنْهَاکُمْ عَنْ مَعْصِیَهٍ إِلاَّ وَأَتَنَاهَى قَبْلَکُمْ عَنْهَا\nاى مردم به خدا سوگند من شما را دعوت به اطاعتى نسبت به اوامر الهى نمى کنم جز اینکه خودم پیش از شما آن را انجام مى دهم و شما را از معصیتى نهى نمى کنم جز اینکه خودم قبلاً آن را ترک مى گویم. قرآن مجید می فرماید :\n《یَا أَیُّهَا الَّذِینَ آمَنُوا لِمَ تَقُولُونَ مَا لاَ تَفْعَلُونَ * کَبُرَ مَقْتآ عِنْدَ اللهِ أَنْ تَقُولُوا مَا لاَ تَفْعَلُونَ ؛ صف – ۳》\nاى کسانى که ایمان آورده اید! چرا سخنى مى گویید که عمل نمى کنید؟! این کار مایه خشم عظیم خداوند است که سخنى بگویید و عمل ننمایید.\n📗شیخ عباس و عمل به مفاتیح:\nدر حالات مرحوم شیخ عباس قمی نوشته اند او یک سال اجازه چاپ مفاتیح الجنان را نداد، وقتی علت را از او پرسیده بودند فرموده بود اول خواستم خودم یک بار به آنچه گفته ام عمل کنم بعد به مردم توصیه کنم.\n📕اهل معروف باشید و به آن امر کنید.\nدر خطبه ۱۲۹ فرمود:\nلَعَنَ اللّه ُ الآمِرینَ بِالمَعروفِ التّارِکینَ لَهُ ، و النّاهینَ عَنِ المُنکَرِ العامِلینَ بِه\nنفرین خدا بر کسانى که به خوبى فرمان مى دهند و خود آن را فرو مى گذارند و بر کسانى که از زشتى باز مى دارند و خود مرتکب آن مى شوند.\n🔻نهمین صفت برادران علی🔻\n💠وَکَانَ إِذَا غُلِبَ عَلَى الْکَلامِ لَمْ یُغْلَبْ عَلَى السُّکُوتِ\nاگر در سخن گفتن مغلوب مى شد هرگز در سکوت کسى بر او غلبه نمى یافت.\nحضرت در نهمین وصف برادر الهی خود مى فرماید برادر من اگر چه در سخن ید طولایی داشت و مسلط به بیان بود ولی حتی اگر کسی در زبان و استدلال بر او پیشی میگرفت، کسی نمی توانست در سکوت بر او غالب شود.\n🟢او کمتر سخن مىگفت و بیشتر سکوت مى کرد به گونه اى که دیگران در سخن گفتن بر او پیشى مى گرفتند؛\nولى هیچکس در سکوت بر او پیشى نمى گرفت و این درواقع نکوهش و مذمتى است از پرگویى و مدح وستایشى است درباره سکوت.\n🔴 حضرت در سومین وصف این برادر نیز فرمود:\nوَکَانَ أَکْثَرَ دَهْرِهِ صَامِتاً فَإِنْ قَالَ بَذَّ الْقَائِلِینَ وَنَقَعَ غَلِیلَ السَّائِلِینَ؛\nفرمود به فرض هم که کسی در گفتار بر او غلبه میکرد، کسی در سکوت بر او غلبه نمیکرد.\n❌بسیاری از گناهان از زبان صادر میشود.\nمی دانیم سخن گفتن خطرات زیادى دارد؛ بسیارى از گناهان کبیره با سخن انجام مى شود و پرهیز از آنان به وسیله سکوت حاصل مى گردد.\nسالکان طریق الى الله یکى از مهمترین مواد برنامه خود را صمت و سکوت مى دانند و هرگز حضور قلب و نیروهاى خود را با سخن گفتن بسیار به هدر نمى دهند و در حال سکوت مى توانند بیشتر درباره عظمت خدا بیندیشند و به اصلاح خویش بپردازند.\nبه همین دلیل افرادى که سکوت فراوان دارند، افرادى فکور و آگاهند.\n\n🟢امام رضا علیه السلام می فرماید:\nعَلامَاتِ الْفِقْهِ الْحِلْمُ وَالْعِلْمُ وَالصَّمْتُ\nاز نشانه هاى فهم و شعور، بردبارى و علم وسکوت است.\nإِنَّ الصَّمْتَ بَابٌ مِنْ أَبْوَابِ الْحِکْمَهِ\nبه یقین سکوت، درى از درهاى دانش است.\nإِنَّ الصَّمْتَ یَکْسِبُ الْمَحَبَّهَ إِنَّهُ دَلِیلٌ عَلَى کُلِّ خَیْرٍ\nسکوت، محبت مردم را به انسان جلب مى کند و راهنما به سوى هر خیر است.\n🔴سکوت در اسرار اهل بیت:\nمرحوم کلینى؛ در باب الصّمْتُ وَحِفْظُ اللِّسانِ؛ روایاتی نقل میکند، برای حفظ زبان مخصوصا در اسرار اهل بیت\nاز امام باقر علیه السلام نقل میکند:\nإِنَّمَا شِیعَتُنَا الْخُرْس‏\nشیعیان ما لال هستند.\nشَهِدْتُ أَبَا عَبْدِ اللَّهِ ع وَ هُوَ یَقُولُ لِمَوْلًى لَهُ یُقَالُ لَهُ سَالِمٌ وَ وَضَعَ یَدَهُ عَلَى شَفَتَیْهِ امام صادق علیه السّلام را دیدم انگشت بالاى لبهاى شریفش گذاشته و بغلامش سالم میفرماید.\nوَ قَالَ یَا سَالِمُ احْفَظْ لِسَانَکَ تَسْلَمْ وَ لَا تَحْمِلِ النَّاسَ عَلَى رِقَابِنَا\nاى سالم زبانت را نگه دار تا سالم بمانى و مردم را بر دوش ما سوار مکن.\nدر طول تاریخ تشیع برخی از امور مثل تبرّی جزء اسرار آل محمد بوده اند و بیان آنها خلاف نظر اهل بیت بوده است.\nاللهم اجعلنا من خیر اعوانه و انصاره","بخش چهارم\nمتن:\nوَ كَانَ عَلَى مَا يَسْمَعُ أَحْرَصَ مِنْهُ عَلَى أَنْ يَتَكَلَّمَ، وَ كَانَ إِذَا بَدَهَهُ أَمْرَانِ يَنْظُرُ أَيُّهُمَا أَقْرَبُ إِلَى الْهَوَى، [فَخَالَفَهُ] فَيُخَالِفُهُ. فَعَلَيْكُمْ بِهَذِهِ الْخَلَائِقِ فَالْزَمُوهَا وَ تَنَافَسُوا فِيهَا، فَإِنْ لَمْ تَسْتَطِيعُوهَا، فَاعْلَمُوا أَنَّ أَخْذَ الْقَلِيلِ خَيْرٌ مِنْ تَرْكِ الْكَثِير.\nترجمه:\nاو بر شنيدن حريص تر بود تا گفتن.\nاو چنان بود كه هرگاه دو كار برايش پيش مى آمد انديشه مى كرد كه كدام به هوا و هوس نزديكتر است، با آن مخالفت مى ورزيد. (و آن را كه خلاف هواى نفس بود مقدم مى شمرد، اگر مى خواهيد راه سعادت و نجات را پيدا كنيد) بر شما باد كه اين صفات را تحصيل كنيد، پيوسته با آن باشيد و از يكديگر در داشتن آنها سبقت بگيريد واگر نمى توانيد همه آنها را انجام دهيد (به مقدار توان انجام دهيد) و بدانيد انجام دادن مقدار كم بهتر از ترك بسيار است.\nتفسیر:\nخلاصه جلسات قبل:\n💠 وَ کَانَ یَقُولُ مَا یَفْعَلُ وَ لا یَقُولُ مَا لا یَفْعَلُ وَ کَانَ إِذَا غُلِبَ عَلَى الْکَلامِ لَمْ یُغْلَبْ عَلَى السُّکُوتِ\nدر بخش های قبل در مورددوری ازدنیا، دوری از شکم پرستی مطالبی، د ر مورد زبان و سکوت مطالبی فرمودند\n🔻دهمین صفت برادران علی🔻\n💠وَکَانَ عَلَى مَا یَسْمَعُ أَحْرَصَ مِنْهُ عَلَى أَنْ یَتَکَلَّمَ\nاو بر شنیدن حریص تر بود تا گفتن.\n🟢حضرت در دهمین وصف برادر الهی خود روی شنیدن تاکید می کنند.\nدر مورد زبان و سکوت مطالبی فرمودند، در این بخش در مورد گوش صحبت میکنند. او گوش خود را وقف شنیدن کرده بود و از یادگرفتن خسته نمیشد.\n+ بسیارى از علوم و دانش هایى که عاید انسان مى شود از طریق شنوایى است. تمام دروس را انسان از استادش با شنیدن فرا مى گیرد و حل مشکلات را از این طریق انجام مى دهد. به خصوص اگر انسان در محضر عالمى حضور پیدا کند، هرچه سکوت واستماعش بیشتر باشد بهره او بیشتر خواهد بود.\nو به عکس اگر در محضر او پرحرفى کند از فواید مهمى محروم خواهد شد.\n+ مسئولین نیز باید گوش شنوا داشته باشند، دردها و نیازهای جامعه را بشنوند و برای برطرف کردن آنها تلاش کنند.\n_وقتی خداوند دو گوش به انسان داده و یک زبان، معنایش این است که شنیدن تو باید دو برابر گفتن تو باشد.\nدادند دو گوش و یک زبانت ز آغاز\nیعنى که دو بشنو و یکى بیش مگو\n🔴از پیامبر که بالاتر نیستیم.\nدر جایی که حتی عالمترین خلائق یعنی پیامبر اکرم نیز نباید به علمش بسنده نماید و مرتب بگوید:\n«قل رَّبّ‏ زِدْنىِ عِلْمًا»؛\nتکلیف دیگران مشخص است که چگونه باید در صدد یادگیری و فهم بر آیند.\n🟢انسانها گرسنه اند، برای گرسنه چه چیزی مهم است.\nدر حکمت ۴۵۷ فرمود:\nمَنْهُومَانِ لَا یَشْبَعَانِ؛ طَالِبُ عِلْمٍ، وَ طَالِبُ دُنْیَا.\nدو گروه گرسنه اند که هرگز سیر نمى شوند: طالب علم و طالب دنیا.\nحرص هم بد است مگر در علم.\nدر خطبه متقین فرمود :\nمِنْ عَلَامَهِ أَحَدِهِمْ أَنَّکَ تَرَى لَهُ قُوَّهً فِی دِینٍ\nاز نشانه هاى هر یک از آنها این است که او را در دین خود قوى مى بینى.\nوَ حَزْماً فِی لِینٍ\nو در عین قاطعیت، نرم خوست،\nوَ إِیمَاناً فِی یَقِینٍ\nداراى ایمانى مملوّ از یقین،\nوَ حِرْصاً فِی عِلْمٍ\nو حرص در کسب دانش دارد.\n🟢یک ساعت شنیدن نهج البلاغه چه ثوابی دارد؟!\nامیرالمومنین صلواه الله علیه فرمود:\nبَینَما أنَا جالِسٌ فی مَسجِدِ النَّبِیِّ إذ دَخَلَ أبو ذَرٍّ فَقالَ:\nدر مسجد پیامبر نشسته بودم که ابوذر وارد شد و گفت:\nیا رَسولَ اللّهِ، جَنازَهُ العابِدِ أحَبُّ إلَیکَ أم مَجلِسُ العِلمِ؟\nاى پیامبر خدا! نزد شما شرکت در تشییع جنازه عابد محبوبتر است یا حضور در مجلس علم؟\nفَقالَ: یا أبا ذَرٍّ،الجُلوسُ ساعَهً عِندَ مُذاکَرَهِ العِلمِ أحَبُّ إلَى اللّهِ مِن ألفِ جَنازَهٍ مِن جَنائِزِ الشُّهَداءِ\nپیامبر فرمود: اى ابوذر! نزد من ساعتى در مجلس علم نشستن، محبوبتر از هزار تشییع جنازه شهید است.\nوالجُلوسُ سَاعَهً عِندَ مُذاکَرَهِ العِلمِ أحَبُّ إلَى اللّهِ مِن قِیامِ ألفِ لَیلَهٍ یُصَلّی فی کُلِّ لَیلَهٍ ألفَ رَکعَهٍ\nو نزد من ساعتى در مجلس علم نشستن، محبوبتر از هزار شب شب زنده دارى است که در هر شب هزار رکعت نماز بخوانى.\nوالجُلوسُ ساعَهً عِندَ مُذاکَرَهِ العِلمِ أحَبُّ إلَى اللّهِ مِن ألفِ غَزوَهٍ و قِراءَهِ القُرآنِ کُلِّهِ. و نزد من لحظه اى در مجلس علم نشستن، محبوبتر از شرکت در هزار غزوه همراه رسول خدا و خواندن همه قرآن است.\nقالَ : یا رَسولَ اللّهِ، مُذاکَرَهُ العِلمِ خَیرٌ مِن قِراءَهِ القُرآنِ کُلِّهِ؟!\nابوذر با تعجب گفت: اى پیامبر خدا! آیا گفت و شنود علمى از خواندن همه قرآن بهتر است؟\nفَقالَ: یا أبا ذَرٍّ، الجُلوسُ ساعَهً عِندَ مُذاکَرَهِ العِلمِ أحَبُّ إلَى اللّهِ مِن قِراءَهِ القُرآنِ کُلِّهِ اثنَی عَشَرَ ألفَ مَرَّهٍ،\nپیامبر فرمود: نزد خدا اى ابوذر! ساعتى در مجلس علم نشستن، محبوبتر از دوازده هزار بار خواندن همه قرآن است.\nعَلَیکُم بِمُذاکَرَهِ العِلمِ، فَإِنَّ بِالعِلمِ تَعرِفونَ الحَلالَ مِنَ الحَرامِ\nهمواره گفت و شنود علمى داشته باشید که با علم ، حلال را از حرام باز مى شناسید.\nیا أباذرٍّ، الجُلوسُ ساعَهً عِندَ مُذاکَرَهِ العِلمِ خَیرٌ لَکَ مِن عِبادَهِ سَنَهٍ صِیامِ نَهارِها وقِیامِ لَیلِها\nاى ابوذر! ساعتى در مجلس علم نشستن براى تو از عبادت یک سال ، که روزهایش را روزه و شبهایش را زنده بدارى، بهتر است.\n🔻یازدهمین صفت برادران علی🔻\n💠 وَ کَانَ إِذَا بَدَهَهُ أَمْرَانِ یَنْظُرُ أَیُّهُمَا أَقْرَبُ إِلَى الْهَوَى فَیُخَالِفُهُ\nاو چنان بود که هرگاه دو کار برایش پیش مى آمد اندیشه مى کرد که کدام به هوا و هوس نزدیکتر است، با آن مخالفت مى ورزید. و آن را که خلاف هواى نفس بود مقدم مى شمرد‌\n🔴حضرت در آخرین وصف برادر الهی خود مى فرماید او سر دو راهی‌ها همیشه از یک قاعده و قانون استفاده میکرد: آن کاری که موافق میل و علاقه نفسانی بود را رها میکرد و آن کاری که مخالف هوس بود را انجام میداد.\n🟢 بسیار مى شود که انسان در زندگى خود بر سر دو راهى قرار مى گیرد که کارى را انجام دهد یا نه و گاه به تردید مى افتد که کدام یک از فعل و ترک یا کدام یک از دو کار متضاد، به رضاى خدا نزدیکتر است. امام علیه السلام در بیان این وصف برادر الهى معیارى بیان فرموده و آن اینکه بنگرد کدام طرف موافق هواى نفس است، آن را رها سازد و به سراغ طرفى برود که برخلاف هواى نفس اوست و این معیارى است براى شناخت حق از باطل در موارد شک و تردید و قرار گرفتن بر سر دو راهى هاى زندگى.\n🔴مخالفت با نفس بهشت است.\nقرآن کریم میفرماید:\n《 وَ أَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَىٰ * فَإِنَّ الْجَنَّهَ هِیَ الْمَأْوَىٰ؛ نازعات – ۴۰》\nو هر کسی از حضور در پیشگاه خداوند بترسد و از هوای نفس دوری کند؛ همانا بهشت منزلگاه اوست.\n❌با دشمن خودمان هم پیمان نشویم.\nپیامبر اکرم صلی الله علیه وآله فرمود :\nأَعدَى عَدُوِّکَ نَفْسُکَ الَّتِی بَینَ جَنْبَیک بزرگترین دشمن، دشمن بیرونی نیست بلکه دشمنی درونی است که همان نفس اماره است.\n🟢مخالفت با نفس ، حاج آقا رحیم ارباب چگونه بود.\nشیخ حسین انصاریان به نقل یکی از شاگردان حاج آقا رحیم ارباب میگفت:\nاگر چه طبع علم و عالم این است که مشهور شود، دیده شود، همه از او سوال کنند و … ولی حاج آقا رحیم ارباب که کوهی از علم و عمل بود در یک مسجد کوچک و برای عده محدودی از فضلا درس میگفت و اصرار داشت در هنگام تدریس پرده های مسجد را بکشند تا کسی او را بر کرسی درس نبیند و با ضعیف ترین صدا درس میگفت تا کسی از بیرون صدای او را به عنوان مدرس نشنود.\nبرادران امیرالمومنین کسانی هستند که اینگونه با نفس مخالفت میکنند.\n❌مخالفت با نفس؛ سختی آسایش ساز دارد.دشخصی از امام صادق پرسید:\nأَیْنَ طَرِیقُ الرَّاحَهِ\nمسیر آسایش و راحتی کجاست؟!\nفَقَالَ فِی خِلَافِ الْهَوَى‏\nحضرت فرمود در مخالفت با هوای نفس است.\nخود مبارزه با نفس سخت است و پیروز شدن بر آن کار مشکلی است ولی راحتی در مبارزه با نفس است.\n🟢 رسیدن به حکمت، از این راه ممکن است. علی بن ابراهیم قمی در تفسیر خود از امام صادق روایت مفصلی نقل میکند که شخصی از حضرت پرسید:\nسَأَلْتُ أَبَا عَبْدِ اللَّهِ ع عَنْ لُقْمَانَ وَ حِکْمَتِهِ از امام صادق پرسیدم چرا خداوند به لقمان حکمت داد.\nفَقَالَ: أَمَا وَ اللَّهِ مَا أُوتِیَ لُقْمَانُ الْحِکْمَهَ بِحَسَبٍ وَ لَا مَالٍ- وَ لَا أَهْلٍ وَ لَا بَسْطٍ فِی جِسْمٍ وَ لَا جَمَالٍ-\nخداوند حکمت را به جهت مقام‌پرستى و ثروت‌پرستى سلیمان به او عطا نفرمود.\nوَ لَکِنَّهُ کَانَ رَجُلًا قَوِیّاً فِی أَمْرِ اللَّهِ\nبلکه به خاطر اهتمام به وظایف الهی به این مقام رسید.\nوَ کَانَ یُکْثِرُ مُجَالَسَهَ الْفُقَهَاءِ وَ الْحُکَمَاءِ همنشینی با اهل علم و حکمت داشت.\nوَ یَتَعَلَّمُ مَا یَغْلِبُ بِهِ نَفْسَهُ وَ یُجَاهِدُ بِهِ هَوَاهُ\nو راه مبارزه و غلبه بر نفس را می آموخت و با هوای نفس مبارزه میکرد.\nنهج البلاغه خوانی که راه علم آموزی است انسان را به حکمت میرساند.\n⏪ امیرالمومنین بعد از بیان یازده صفت اخلاقی بی نظیری که در این برادر الهی بود، خطاب به همه کسانی که این صفات را شنیدند میفرماید:\nفَعَلَیْکُمْ بِهَذِهِ الْخَلائِقِ\nاگر مى خواهید راه سعادت و نجات را پیدا کنید بر شما باد که این صفات را به دست آورید.\nفَالْزَمُوهَا\nپیوسته با آن ملازم باشید.\nوَ تَنَافَسُوا فِیهَا\nو برای رسیدن به این جایزه نفیس با یکدیگر مسابقه بدهید.\nفَإِنْ لَمْ تَسْتَطِیعُوهَا فَاعْلَمُوا أَنَّ أَخْذَ الْقَلِیلِ خَیْرٌ مِنْ تَرْکِ الْکَثِیرِ\nو اگر نمى توانید همه آنها را انجام دهید به مقدار توان انجام دهید، و بدانید انجام مقدار کم بهتر از ترک همه است.\n⏪در این توصیه پایانی که در واقع جمع بندی همه مباحث است، حضرت چند توصیه دارند:\n◀️۱. کسب این اخلاق\n◀️۲. التزام به این اخلاق\n(اینگونه نباشد که مقطعی و فصلی به این اخلاق عمل کنیم)\n◀️۳. مسابقه در راه کسب فضائل\n◀️۴. عمل به حداقل ها، عمل به برخی از این اخلاق، عمل به بخشی از این یازده توصیه.\nمَا لا یُدرَک کُلُه لا یُدرَک کُلُه\n🟢برادران امیرالمومنین اهل مسابقه اند. در مسیر حق، باید مسابقه داد، پیشتاز شد، جزء سابقون شد، و به ندای “سَارِعُوا إِلَىٰ مَغْفِرَهٍ مِنْ رَبِّکُمْ”\nلبیک گفت.\nامام سجاد علیه السلام فرمود:\nمَعَاشِرَ شِیعَتِنَا أَمَّا الْجَنَّهُ فَلَنْ تَفُوتَکُمْ سَرِیعاً کَانَ أَوْ بَطِیئاً\nاى شیعیان ما! شما بهشت را هرگز از دست نمى‌دهید، دیر یا زود به آن وارد خواهید شد،\nوَ لَکِنْ تَنَافَسُوا فِی الدَّرَجَاتِ\nاما براى رسیدن به درجات آن با هم رقابت کنید!،\nوَ اعْلَمُوا أَنَّ أَرْفَعَکُمْ دَرَجَاتٍ،\nبدانیدکسی در بهشت درجه اش بالاتر است\nوَ أَحْسَنَکُمْ قُصُوراً وَ دُوراً وَ أَبْنِیَهً فِیهَا:\nو از قصرها و خانه ها و بناهای بهتر آنجا برخوردار است…\nأَحْسَنُکُمْ إِیجَاباً لِإِخْوَانِهِ الْمُؤْمِنِینَ،\nهرکس از شما که بهتر به درخواستهای برادران دینیش پاسخ دهد.\nوَ أَکْثَرُکُمْ مُوَاسَاهً لِفُقَرَائِهِمْ\nو مواسات مشارکت در امور معاش بیشتر با فقرای ایمانی داشته باشد،\n🔴شیعیان بهشتی اند، برای درجات مسابقه دهید.\nامام صادق علیه السلام فرمود :\nوَ اللَّهِ مَا بَعْدَنَا غَیْرُکُمْ وَ إِنَّکُمْ مَعَنَا فِی السَّنَامِ الْأَعْلَى\nبه خدا قسم غیر از شما کسی پیرو ما نخواهد بود و شما با ما هستید، در برترین درجات و مقام ها.\nفَتَنَافَسُوا فِی الدَّرَجَاتِ.\nپس بر یکدیگر پیشی گیرید و با هم رقابت کنید برای رسیدن به درجات بهشت.\nکه در زیارت حضرت معصومه میخوانیم\n” یا فاطمه اشفعی لی فی الجنه”\n🟢برای رسیدن به حوض کوثر مسابقه دهید.\nامیرالمومنین علیه السلام فرمود:\nأَنَا وَ رَسُولُ اللَّهِ ص عَلَى الْحَوْضِ وَ مَعَنَا عِتْرَتُنا\nما اهل بیت صاحب حوض کوثر هستیم،\nفَمَنْ أَرَادَنَا فَلْیَأْخُذْ بِقَوْلِنَا وَ لْیَعْمَلْ بِأَعْمَالِنَا\nفَإِنَّا أَهْلُ البیت‏ لَنَا شَفَاعَهٌ فَتَنَافَسُوا فِی لِقَائِنَا عَلَى الْحَوْضِ\nهر کسی میخواهد پیشی بگیرد در رسیدن به حوض کوثر گفتار ما را یاد بگیرد و به آنها عمل کند.\n🔴کامل الزیارات، مسابقه برای زیارت امام حسین :\nامام صادق علیه السلام فرمود:\nلَا تَدَعُوا زِیَارَتَهُ- یَمُدُّ اللَّهُ فِی أَعْمَارِکُمْ وَ یَزِیدُ فِی أَرْزَاقِکُمْ\nزیارت امام حسین را ترک نکنید چرا که طول عمر و افزایش روزی به همراه دارد. فَتَنَافَسُوا فِی زِیَارَتِهِ وَ لَا تَدَعُوا ذَلِکَ فَإِنَّ الْحُسَیْنَ شَاهِدٌ لَکُمْ فِی ذَلِکَ عِنْدَ اللَّهِ وَ عِنْدَ رَسُولِهِ وَ عِنْدَ فَاطِمَهَ وَ عِنْدَ أَمِیرِ الْمُؤْمِنِینَ.\nبرای زیارت امام حسین با هم مسابقه بدهید و امام حسین نزد خدا و پیامبرو امیرالمومنین و حضرت زهرا بر این تلاش و مسابقه شما شهادت خواهد داد.\n🔻نکته:\nاین حکمت در مورد برادران امیرالمومنین بود ” کَانَ لِی فِیمَا مَضَى أَخٌ فِی اللَّهِ “\nما هم میتوانیم از برادران امیرالمومنین باشیم.\nدر خطبه ۱۸۲ که یک هفته قبل از شهادت امیرالمومنین ایراد شد فرمود:\nأَیْنَ إِخْوَانِیَ الَّذِینَ رَکِبُوا الطَّرِیقَ وَ مَضَوْا عَلَى الْحَقِّ؟\nکجایند برادران من؟ همانها که در مسیر صحیح گام نهادند و در راه حق پیش افتادند.\nأَیْنَ عَمَّارٌ وَ أَیْنَ ابْنُ التَّیِّهَانِ وَ أَیْنَ ذُو الشَّهَادَتَیْنِ\nکجاست «عمار»؟ کجاست «ابن تیّهان»؟ و کجاست «ذوالشهادتین».\nوَ أَیْنَ نُظَرَاؤُهُمْ مِنْ إِخْوَانِهِمُ الَّذِینَ تَعَاقَدُوا عَلَى الْمَنِیَّهِ وَ اُبْرِدَ بِرُءُوسِهِمْ إِلَى الْفَجَرَهِ؟\nو کجایند کسانى همچون آنان از برادرانشان که پیمان بر جان بستند و سرانجام سرهایشان براى فاجران فرستاده شد!\n⏪برادران امیرالمومنین کسانی هستند که:\n◀️ رَکِبُوا الطَّرِیقَ :\nبرادران علی سوار راه هستند وقتی راه را پیدا کردند دیگر میروند و معطل کسی نمیشوند. و در این مسیر به هیچ مشوق نیاز ندارند.\n◀️ مَضَوْا عَلَى الْحَقِّ :\nبرادران علی حق گرا و حق طلب هستند، وقتی حق را یافتند در مقابل آن نمی ایستند و چیزی جز حق نمی خواهند.\n◀️ برادران علی علیه السلام مثل عمار جهاد تبیین دارند؛\nمثل مالک بن تیّهان بصیرت دارند و تا صفین در رکاب حضرت هستند و به شهادت میرسند،\nمثل ذو شهادتین معرفتی به پیامبر دارند که شهادت آنها در محکمه به مانند شهادت دو نفر است.\n◀️ تَعَاقَدُوا عَلَى الْمَنِیَّهِ:\nبرادران حضرت کسانی هستند که پیمان جان بسته اند، که در مسیر اهل بیت تا پای جان می ایستند.\n◀️ اُبْرِدَ بِرُءُوسِهِمْ إِلَى الْفَجَرَهِ:\nبرادران علی کسانی هستند که پایان کارشان مبارزه و مقابله با کفار و فاجران است و در این راه به شهادت میرسند و سر آنها را برای دشمنان میبرند (دشمن برای سر آنها جایزه تعیین کرده است)\n🟢کاش ما جزء برادران رسول الله باشیم.\nقَالَ رَسُولُ اللَّهِ ص ذَاتَ یَوْمٍ وَ عِنْدَهُ جَمَاعَهٌ مِنْ أَصْحَابِهِ\nروزی پیامبر در حالی که عدّه‌ای از یارانش نزد او بودند، فرمود:\nاللَّهُمَّ لَقِّنِی إِخْوَانِی مَرَّتَیْنِ\nخداوندا! برادران مرا به من نشان بده! حضرت این سخن را دو مرتبه تکرار کردند.\nفَقَالَ مَنْ حَوْلَهُ مِنْ أَصْحَابِهِ أَمَا نَحْنُ إِخْوَانُکَ یَا رَسُولَ اللَّهِ\nدر این هنگام گروهی از یاران که گرد آن حضرت بودند، گفتند: ای پیامبر خدا! آیا ما برادران شما نیستیم؟\nفَقَالَ لَا إِنَّکُمْ أَصْحَابِی وَ إِخْوَانِی قَوْمٌ مِنْ آخِرِ الزَّمَانِ آمَنُوا بِی وَ لَمْ یَرَوْنِی\nفرمود: نه! شما یاران من هستید برادران من قومی هستند که در آخرالزمان خواهند آمد. آنها به من ایمان می‌آورند، در حالی که مرا ندیده اند.\nهر یک از آنها بر دین خود پایدار می‌ماند\nأُولَئِکَ مَصَابِیحُ الدُّجَى یُنْجِیهِمُ اللَّهُ مِنْ کُلِّ فِتْنَهٍ غَبْرَاءَ مُظْلِمَهٍ.\nآنها چراغی فروزانی در دل تاریک شب هستند. خداوند آنها را از همه فتنه‌های تیره و تار در امان نگه می‌دارد!\n🔻نکته:\nمرحوم کلینی در کافی عین این حکمت را از امام مجتبی نقل میکند:\nخَطَبَ النَّاسَ الْحَسَنُ بْنُ عَلِیٍّ ص فَقَالَ أَیُّهَا النَّاسُ أَنَا أُخْبِرُکُمْ عَنْ أَخٍ لِی کَانَ مِنْ أَعْظَمِ النَّاسِ فِی عَیْنِی\nعلامه شوشتری نیز در ابتدای شرح این حکمت میفرماید روایات فراوان شیعه و سنی این حدیث را از امام حسن نقل کرده اند و اصلا معلوم نیست سید رضی بر چه مبنا و سندی این حدیث را از امیرالمومنین نقل کرده است.\nاللهم اجعلنا من خیر اعوانه و انصاره"]});
